function normalizeBill(bill){const total=Number(bill.total)||0;if(!Number.isFinite(Number(bill.paidAmount)))bill.paidAmount=bill.status==='Paid'?total:0;bill.paidAmount=Math.max(0,Math.min(total,Number(bill.paidAmount)||0));if(!Array.isArray(bill.payments))bill.payments=bill.paidAmount>0?[{date:bill.date,amount:bill.paidAmount,method:bill.method||'—'}]:[];return bill;}
function loadStore(){
  let loaded;
  try{const saved=JSON.parse(localStorage.getItem(STORAGE_KEY));if(saved&&typeof saved==='object')loaded=saved;}catch(error){}
  if(!loaded)loaded=structuredClone(seed);
  loaded.profile={...seed.profile,...(loaded.profile||{})};
  loaded.products=Array.isArray(loaded.products)?loaded.products:[];
  loaded.bills=Array.isArray(loaded.bills)?loaded.bills:[];
  loaded.customers=Array.isArray(loaded.customers)?loaded.customers:[];
  loaded.purchases=Array.isArray(loaded.purchases)?loaded.purchases:[];
  loaded.customers.forEach((customer,index)=>{if(!customer.id)customer.id='C-'+(1001+index);});
  loaded.products.forEach(product=>{if(!Number.isFinite(Number(product.purchaseRate))){product.purchaseRate=Math.round(Number(product.price||0)*0.8*100)/100;product.purchaseRateEstimated=true;}if(!product.supplier)product.supplier='Opening stock';if(!product.lastPurchaseDate)product.lastPurchaseDate='';});
  loaded.bills.forEach(normalizeBill);
  return loaded;
}function saveStore({syncSheets=true}={}){try{const snapshot=JSON.stringify(store);localStorage.setItem(STORAGE_KEY,snapshot);localStorage.setItem(LOCAL_UPDATED_KEY,String(Date.now()));const status=document.querySelector('#save-status');if(status){status.textContent=pythonBackendConnected?'Saved locally · syncing SQLite':'✓ Saved in this browser';status.classList.remove('save-error');}if(syncSheets)window.dispatchEvent(new Event('bahipro:store-saved'));if(pythonBackendConnected)saveWorkspaceToPython(JSON.parse(snapshot)).then(()=>{if(currentPage==='overview')loadPythonSuggestions();}).catch(()=>{pythonBackendConnected=false;const current=document.querySelector('#save-status');if(current){current.textContent='Saved locally · Python sync failed';current.classList.add('save-error');}});}catch(error){const status=document.querySelector('#save-status');if(status){status.textContent='Save failed';status.classList.add('save-error');}toast('Could not save your changes in this browser.');}}function money(value){return '₹'+Number(value||0).toLocaleString('en-IN');}
function dueAmount(bill){return Math.max(0,Number(bill.total||0)-Number(bill.paidAmount||0));}
function dateLabel(value){const d=new Date(value+'T00:00:00');return d.toLocaleDateString('en-IN',{day:'2-digit',month:'short'});}
function localISODate(date=new Date()){const offset=date.getTimezoneOffset()*60000;return new Date(date.getTime()-offset).toISOString().slice(0,10);}
function escapeHtml(value){return String(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));}
function initials(name){return String(name||'').trim().split(/\s+/).filter(Boolean).map(x=>x[0]).slice(0,2).join('').toUpperCase()||'S';}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600);}
function setPage(page){currentPage=page;document.querySelectorAll('.nav-item[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===page));document.querySelector('#crumb-label').textContent=({overview:'Overview',billing:'Billing',inventory:'Inventory',customers:'Customers',reports:'Reports',settings:'Settings'})[page]||'Overview';renderPage();}
function lowStock(){return store.products.filter(p=>p.stock<=p.reorder);}
function currentMonthBills(){const month=localISODate().slice(0,7);return store.bills.filter(b=>String(b.date||'').startsWith(month));}
function currentMonthPurchases(){const month=localISODate().slice(0,7);return store.purchases.filter(p=>String(p.date||'').startsWith(month));}
function sumBills(bills){return bills.reduce((sum,bill)=>sum+Number(bill.total||0),0);}
function sumCollected(bills){return bills.reduce((sum,bill)=>sum+Number(bill.paidAmount||0),0);}
function categoryBreakdown(){const totals=new Map();store.bills.forEach(bill=>{if(bill.lines?.length)bill.lines.forEach(line=>{const category=line.category||'Other';totals.set(category,(totals.get(category)||0)+Number(line.lineTotal||0));});else if(Number(bill.total)>0)totals.set('Other',(totals.get('Other')||0)+Number(bill.total));});return [...totals].map(([name,value])=>({name,value})).sort((a,b)=>b.value-a.value);}
function topSellingProducts(){const totals=new Map();store.bills.forEach(bill=>(bill.lines||[]).forEach(line=>{const key=line.productId||line.productName,old=totals.get(key)||{name:line.productName,category:line.category||'Product',quantity:0};old.quantity+=Number(line.quantity||0);totals.set(key,old);}));return [...totals.values()].sort((a,b)=>b.quantity-a.quantity).slice(0,4);}
function salesChartData(){const now=new Date(),keyFor=d=>localISODate(d),sumFor=key=>store.bills.filter(b=>b.date===key).reduce((sum,b)=>sum+Number(b.total||0),0),total=values=>values.reduce((sum,value)=>sum+value,0);let labels=[],values=[],prev=[];if(period==='day'){const today=new Date(now.getFullYear(),now.getMonth(),now.getDate()),days=[-1,0],previous=[-2,-1];labels=['Yesterday','Today'];values=days.map(offset=>{const d=new Date(today);d.setDate(d.getDate()+offset);return sumFor(keyFor(d));});prev=previous.map(offset=>{const d=new Date(today);d.setDate(d.getDate()+offset);return sumFor(keyFor(d));});}else if(period==='week'){const today=new Date(now.getFullYear(),now.getMonth(),now.getDate()),monday=new Date(today);monday.setDate(today.getDate()-((today.getDay()+6)%7));labels=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];values=labels.map((_,i)=>{const d=new Date(monday);d.setDate(monday.getDate()+i);return sumFor(keyFor(d));});prev=labels.map((_,i)=>{const d=new Date(monday);d.setDate(monday.getDate()-7+i);return sumFor(keyFor(d));});}else{const year=now.getFullYear(),month=now.getMonth(),thisMonth=new Date(year,month,1),lastMonth=new Date(year,month-1,1);labels=['Wk 1','Wk 2','Wk 3','Wk 4','Wk 5'];const weekSums=start=>labels.map((_,i)=>store.bills.filter(b=>{const d=new Date(`${b.date}T00:00:00`);return d.getFullYear()===start.getFullYear()&&d.getMonth()===start.getMonth()&&Math.ceil(d.getDate()/7)===i+1;}).reduce((sum,b)=>sum+Number(b.total||0),0));values=weekSums(thisMonth);prev=weekSums(lastMonth);}const currentTotal=total(values),previousTotal=total(prev),change=previousTotal?`${((currentTotal-previousTotal)/previousTotal*100).toFixed(1)}% vs. previous period`:currentTotal?'New sales recorded':'No sales yet';return{labels,values,prev,total:money(currentTotal),change};}
function billRows(list,showActions=false){if(!list.length)return `<tr><td colspan="${showActions?7:6}" class="empty-row">${store.bills.length?'No bills match your search.':'No bills yet. Create your first bill to get started.'}</td></tr>`;return list.map(b=>`<tr><td><strong>${escapeHtml(b.id)}</strong></td><td>${escapeHtml(b.customer)}</td><td>${dateLabel(b.date)}</td><td>${b.items} items</td><td><strong>${money(b.total)}</strong>${b.paidAmount>0&&dueAmount(b)>0?`<br><span class="muted-small">${money(b.paidAmount)} paid · ${money(dueAmount(b))} due</span>`:''}</td><td><span class="status-pill ${b.status==='Pending'?'pending':''}">${escapeHtml(b.status)}</span></td>${showActions?`<td><span class="row-actions"><button class="table-link" data-preview-bill="${escapeHtml(b.id)}">Preview</button>${dueAmount(b)>0?`<button class="table-link" data-mark-paid="${escapeHtml(b.id)}">${b.paidAmount>0?'Add payment':'Record payment'}</button>`:''}</span></td>`:''}</tr>`).join('');}function productRows(list){if(!list.length)return '<tr><td colspan="10" class="empty-row">No products match your search.</td></tr>';return list.map(p=>{const margin=Number(p.price||0)-Number(p.purchaseRate||0);return `<tr><td><div class="product-cell"><span class="product-thumb">${p.emoji||'📦'}</span><span><strong>${escapeHtml(p.name)}</strong><br><span class="muted-small">${escapeHtml(p.id)}</span></span></div></td><td>${escapeHtml(p.category)}</td><td>${money(p.price)}</td><td>${money(p.purchaseRate)}${p.purchaseRateEstimated?'<br><span class="muted-small estimate-tag">Estimated</span>':''}</td><td><strong class="${margin<0?'negative-margin':''}">${money(margin)}</strong></td><td><strong>${p.stock}</strong></td><td>${p.reorder}</td><td>${escapeHtml(p.supplier||'—')}</td><td>${p.stock<=p.reorder?'<span class="status-pill pending">Restock</span>':'<span class="status-pill">In stock</span>'}</td><td><span class="row-actions"><button class="table-link" data-product-edit="${escapeHtml(p.id)}">Edit</button><button class="table-link" data-adjust="${escapeHtml(p.id)}">Adjust</button><button class="table-link danger-link" data-product-remove="${escapeHtml(p.id)}">Remove</button></span></td></tr>`}).join('');}function dashboard(){const dashboardGreeting=store.profile.name?.trim()?`Good morning, ${escapeHtml(store.profile.name.trim().split(/\s+/)[0])}`:'Your store, ready to go';const monthBills=currentMonthBills(),monthSales=sumBills(monthBills),today=localISODate(),todayRevenue=sumBills(store.bills.filter(b=>b.date===today)),average=monthBills.length?monthSales/monthBills.length:0,stockValue=store.products.reduce((a,p)=>a+Number(p.purchaseRate||0)*p.stock,0),low=lowStock(),outstanding=store.bills.filter(b=>b.status==='Pending').reduce((sum,b)=>sum+dueAmount(b),0),categories=categoryBreakdown(),categoryTotal=categories.reduce((sum,c)=>sum+c.value,0),palette=['#185fa9','#6397d2','#a8c7eb','#e6b274','#95b9e1'],topProducts=topSellingProducts();let cursor=0;const donutGradient=categoryTotal?categories.map((item,index)=>{const start=cursor;cursor+=item.value/categoryTotal*100;return `${palette[index%palette.length]} ${start.toFixed(2)}% ${cursor.toFixed(2)}%`;}).join(','):'#e9eeeb 0 100%';const categoryRows=categories.slice(0,5).map((item,index)=>`<div class="category-row"><i class="category-dot" style="background:${palette[index%palette.length]}"></i>${escapeHtml(item.name)} <strong>${categoryTotal?Math.round(item.value/categoryTotal*100):0}%</strong></div>`).join('')||'<span class="muted-small">No category sales yet</span>';const categoryInsight=categories.length?`<strong>${escapeHtml(categories[0].name)} leads sales.</strong> It makes up ${Math.round(categories[0].value/categoryTotal*100)}% of recorded sales.`:'Create your first bill to see your sales mix here.';const topRows=topProducts.map(item=>`<div class="stock-row"><span class="product-thumb">📦</span><span class="stock-info"><strong>${escapeHtml(item.name)}</strong><small>${escapeHtml(item.category)}</small></span><span class="stock-count"><strong style="color:#286db5">${item.quantity} sold</strong></span></div>`).join('')||'<p class="muted-small">Top sellers will appear after your first bill.</p>';return `<div class="page-heading"><div><p class="eyebrow">YOUR RETAIL WORKSPACE</p><h1>${dashboardGreeting} <span style="font-size:19px">☀️</span></h1><p>Here’s what’s happening at your store today.</p></div><div class="heading-actions"><button class="btn" data-action="export-bills"><span class="btn-icon">↓</span> Export report</button><button class="btn btn-primary" data-action="new-bill"><span class="btn-icon">＋</span> Create bill</button></div></div><div class="metrics-grid"><article class="metric-card"><div class="metric-top"><span class="metric-label">Today's revenue</span><span class="metric-icon">↗</span></div><div class="metric-value">${money(todayRevenue)}</div><div class="metric-foot"><span>${store.bills.filter(b=>b.date===today).length} bills today</span></div></article><article class="metric-card"><div class="metric-top"><span class="metric-label">Bills this month</span><span class="metric-icon blue">▤</span></div><div class="metric-value">${monthBills.length}</div><div class="metric-foot"><span>Recorded invoices</span></div></article><article class="metric-card"><div class="metric-top"><span class="metric-label">Average bill value</span><span class="metric-icon orange">₹</span></div><div class="metric-value">${money(average)}</div><div class="metric-foot"><span>This month</span></div></article><article class="metric-card"><div class="metric-top"><span class="metric-label">Low stock items</span><span class="metric-icon pink">⚑</span></div><div class="metric-value">${String(low.length).padStart(2,'0')}</div><div class="metric-foot"><span class="trend down">Needs attention</span><span data-go="inventory" class="table-link">View items →</span></div></article></div><div class="dashboard-grid"><section class="panel"><div class="panel-heading"><div><h2>Sales overview</h2><p>Track your recorded sales</p></div><div class="segmented" id="period-controls"><button data-period="day" class="${period==='day'?'active':''}">Day</button><button data-period="week" class="${period==='week'?'active':''}">Week</button><button data-period="month" class="${period==='month'?'active':''}">Month</button></div></div><div class="chart-total" id="chart-total">${money(sumBills(store.bills))} <small>Recorded sales</small></div><div class="chart-wrap"><div class="chart-tooltip" id="chart-tooltip"></div><svg id="sales-chart" viewBox="0 0 700 190" role="img" aria-label="Recorded sales trend"></svg></div><div class="chart-legend"><span><i class="legend-dot"></i>This period</span><span><i class="legend-dot muted"></i>Previous period</span></div></section><section class="panel"><div class="panel-heading"><div><h2>Sales by category</h2><p>Based on saved bill items</p></div><button class="table-link" data-go="reports">See report →</button></div><div class="breakdown-total">${money(categoryTotal)} <small>recorded sales</small></div><div class="donut-area"><div class="donut" style="background:${donutGradient}"><div class="donut-center"><strong>${store.bills.length}</strong><span>bills made</span></div></div><div class="category-legend">${categoryRows}</div></div><div class="insight-banner"><span class="insight-icon">✦</span><p>${categoryInsight}</p></div></section></div><div class="bottom-grid"><section class="panel table-panel"><div class="panel-heading"><div><h2>Recent bills</h2><p>Your latest customer transactions</p></div><button class="table-link" data-go="billing">View all →</button></div><div class="table-wrap"><table><thead><tr><th>INVOICE</th><th>CUSTOMER</th><th>DATE</th><th>ITEMS</th><th>AMOUNT</th><th>STATUS</th></tr></thead><tbody>${billRows(store.bills.slice(0,5))}</tbody></table></div></section><section class="panel"><div class="panel-heading"><div><h2>Restock reminders</h2><p>${low.length} products below their reorder level</p></div><button class="table-link" data-go="inventory">View all →</button></div><div class="stock-list">${low.slice(0,4).map(p=>`<div class="stock-row"><span class="product-thumb">${p.emoji||'📦'}</span><span class="stock-info"><strong>${escapeHtml(p.name)}</strong><small>${escapeHtml(p.category)}</small></span><span class="stock-count"><strong>${p.stock} left</strong><small>Min. ${p.reorder}</small></span></div>`).join('')||'<p class="muted-small">Everything is well stocked.</p>'}</div></section></div><div class="bottom-grid"><section class="panel"><div class="panel-heading"><div><h2>Business snapshot</h2><p>A quick pulse check for your store</p></div><span class="status-pill">Live</span></div><div class="snapshot-grid"><div><span class="muted-small">Stock value at latest rates</span><strong>${money(stockValue)}</strong></div><div><span class="muted-small">Total sales recorded</span><strong>${money(sumBills(store.bills))}</strong></div><div><span class="muted-small">Outstanding bills</span><strong>${money(outstanding)}</strong></div></div></section><section class="panel"><div class="panel-heading"><div><h2>Top selling products</h2><p>Ranked from saved bills</p></div><button class="table-link" data-go="inventory">Inventory →</button></div><div class="stock-list">${topRows}</div></section></div>${bahiProAIPanel()}`;}function billingPage(){const bills=currentMonthBills(),sales=sumBills(bills),collected=sumCollected(bills),pending=store.bills.filter(b=>b.status==='Pending'),due=pending.reduce((sum,b)=>sum+dueAmount(b),0);return `<div class="page-heading"><div><p class="eyebrow">SALES &amp; PAYMENTS</p><h1>Billing</h1><p>Create invoices and keep track of every sale.</p></div><div class="heading-actions"><button class="btn" data-action="export-bills"><span class="btn-icon">↓</span> Export bills</button><button class="btn btn-primary" data-action="new-bill"><span class="btn-icon">＋</span> New bill</button></div></div><div class="metrics-grid"><article class="metric-card"><div class="metric-top"><span class="metric-label">Sales this month</span><span class="metric-icon">₹</span></div><div class="metric-value">${money(sales)}</div><div class="metric-foot"><span>${bills.length} invoices</span></div></article><article class="metric-card"><div class="metric-top"><span class="metric-label">Total invoices</span><span class="metric-icon blue">▤</span></div><div class="metric-value">${bills.length}</div><div class="metric-foot"><span>So far this month</span></div></article><article class="metric-card"><div class="metric-top"><span class="metric-label">Collected this month</span><span class="metric-icon">✓</span></div><div class="metric-value">${money(collected)}</div><div class="metric-foot"><span>Recorded payments</span></div></article><article class="metric-card"><div class="metric-top"><span class="metric-label">Awaiting payment</span><span class="metric-icon orange">◷</span></div><div class="metric-value">${money(due)}</div><div class="metric-foot"><span class="trend down">${pending.length} pending bills</span></div></article></div><div class="section-toolbar"><div class="toolbar-left"><h2>All bills</h2><span class="muted-small">${store.bills.length} saved invoices</span></div><div class="toolbar-left"><input class="inline-search" data-table-search placeholder="Search invoice or customer…"><select class="filter-select" id="bill-filter"><option value="all">All statuses</option><option>Paid</option><option>Pending</option></select></div></div><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>INVOICE</th><th>CUSTOMER</th><th>DATE</th><th>ITEMS</th><th>AMOUNT</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody id="bills-table">${billRows(store.bills,true)}</tbody></table></div></section>`;}function nextPurchaseId(){const used=new Set(store.purchases.map(p=>p.id));let number=1;while(used.has(`PUR-${String(number).padStart(4,'0')}`))number++;return `PUR-${String(number).padStart(4,'0')}`;}
function purchaseDue(purchase){return Math.max(0,Number(purchase.total||0)-Number(purchase.paidAmount||0));}
function purchaseRows(list){if(!list.length)return `<tr><td colspan="9" class="empty-row">${store.purchases.length?'No purchases match your search.':'No purchases recorded yet. Receive stock to add your first purchase.'}</td></tr>`;return list.map(p=>`<tr><td><strong>${escapeHtml(p.invoiceNumber||p.id)}</strong><br><span class="muted-small">${escapeHtml(p.id)}</span></td><td>${dateLabel(p.date)}</td><td>${escapeHtml(p.supplier)}</td><td>${p.lines.length} products · ${p.items} units</td><td><strong>${money(p.total)}</strong></td><td>${money(p.paidAmount)}</td><td>${purchaseDue(p)>0?`<strong>${money(purchaseDue(p))}</strong>`:'—'}</td><td><span class="status-pill ${p.status==='Paid'?'':'pending'}">${escapeHtml(p.status)}</span></td><td><button class="table-link" data-purchase-view="${escapeHtml(p.id)}">Details</button></td></tr>`).join('');}
function purchasesPage(){const month=currentMonthPurchases(),monthTotal=month.reduce((sum,p)=>sum+Number(p.total||0),0),payables=store.purchases.reduce((sum,p)=>sum+purchaseDue(p),0),units=month.reduce((sum,p)=>sum+Number(p.items||0),0);return `<div class="page-heading"><div><p class="eyebrow">SUPPLIERS &amp; STOCK COSTS</p><h1>Purchases</h1><p>Record supplier invoices, purchase rates, and payments. Received quantities update inventory.</p></div><div class="heading-actions"><button class="btn" data-action="export-purchases"><span class="btn-icon">↓</span> Export purchases</button><button class="btn btn-primary" data-action="new-purchase"><span class="btn-icon">＋</span> Record purchase</button></div></div><div class="metrics-grid"><article class="metric-card"><div class="metric-top"><span class="metric-label">Purchases this month</span><span class="metric-icon orange">₹</span></div><div class="metric-value">${money(monthTotal)}</div><div class="metric-foot"><span>${month.length} supplier invoices</span></div></article><article class="metric-card"><div class="metric-top"><span class="metric-label">Invoices this month</span><span class="metric-icon blue">▤</span></div><div class="metric-value">${month.length}</div><div class="metric-foot"><span>Recorded purchases</span></div></article><article class="metric-card"><div class="metric-top"><span class="metric-label">Supplier payables</span><span class="metric-icon pink">◷</span></div><div class="metric-value">${money(payables)}</div><div class="metric-foot"><span>Remaining purchase balances</span></div></article><article class="metric-card"><div class="metric-top"><span class="metric-label">Units received this month</span><span class="metric-icon">↙</span></div><div class="metric-value">${units}</div><div class="metric-foot"><span>Added to stock</span></div></article></div><div class="section-toolbar"><div class="toolbar-left"><h2>Purchase history</h2><span class="muted-small">${store.purchases.length} invoices</span></div><div class="toolbar-left"><input class="inline-search" data-purchase-search placeholder="Search supplier or invoice…"><select class="filter-select" id="purchase-filter"><option value="all">All payments</option><option value="Paid">Paid</option><option value="Partially paid">Partially paid</option><option value="Pending">Pending</option></select></div></div><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>INVOICE</th><th>DATE</th><th>SUPPLIER</th><th>ITEMS</th><th>PURCHASE TOTAL</th><th>PAID</th><th>BALANCE</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody id="purchases-table">${purchaseRows(store.purchases)}</tbody></table></div></section>`;}
function purchaseLineMarkup(){return `<div class="purchase-line" data-purchase-line><div class="form-field"><label>Product</label><input class="field" data-purchase-product list="purchase-product-options" placeholder="Search product…" required><small class="line-hint">Choose an item from inventory</small></div><div class="form-field"><label>Quantity</label><input class="field" data-purchase-quantity type="number" min="1" step="1" value="1" required></div><div class="form-field"><label>Purchase rate (₹)</label><input class="field" data-purchase-rate type="number" min="0.01" step="0.01" placeholder="0.00" required></div><button type="button" class="remove-line" data-remove-purchase-line aria-label="Remove purchase item">×</button></div>`;}
function addPurchaseLine(){const host=document.querySelector('#purchase-lines');if(!host)return;host.insertAdjacentHTML('beforeend',purchaseLineMarkup());updatePurchaseTotal();}
function updatePurchaseTotal(){const rows=[...document.querySelectorAll('[data-purchase-line]')];const total=rows.reduce((sum,row)=>sum+(Number(row.querySelector('[data-purchase-quantity]').value)||0)*(Number(row.querySelector('[data-purchase-rate]').value)||0),0);const target=document.querySelector('#purchase-total');if(target)target.textContent=money(total);const balance=document.querySelector('#purchase-balance-preview');if(balance){const mode=document.querySelector('#purchase-payment-status')?.value||'pending',paid=mode==='paid'?total:mode==='partial'?(Number(document.querySelector('#purchase-paid-amount')?.value)||0):0;balance.textContent=money(Math.max(0,total-paid));}}
function openPurchaseModal(){const host=document.querySelector('#modal-content'),options=store.products.map(p=>`<option value="${escapeHtml(p.name)}">${escapeHtml(p.category)} · ${p.stock} in stock</option>`).join('');host.innerHTML=`<h2 id="modal-title">Record a purchase</h2><p class="modal-intro">Enter the supplier invoice and item costs. Quantities received increase stock.</p><form id="purchase-form"><div class="form-grid"><div class="form-field"><label for="purchase-supplier">Supplier name</label><input class="field" id="purchase-supplier" required placeholder="e.g. North Star Distributors"></div><div class="form-field"><label for="purchase-invoice">Supplier invoice / reference</label><input class="field" id="purchase-invoice" placeholder="Optional reference"></div><div class="form-field"><label for="purchase-date">Purchase date</label><input class="field" id="purchase-date" type="date" value="${localISODate()}" required></div><div class="form-field"><label for="purchase-payment-status">Payment status</label><select class="field" id="purchase-payment-status"><option value="pending">Leave pending</option><option value="partial">Partially paid</option><option value="paid">Paid in full</option></select></div></div><datalist id="purchase-product-options">${options}</datalist><div class="bill-lines-heading"><strong>Purchased items</strong><button type="button" class="table-link" data-add-purchase-line>＋ Add item</button></div><div id="purchase-lines">${purchaseLineMarkup()}</div><div class="form-grid purchase-payment-fields" id="purchase-payment-fields" hidden><div class="form-field" id="purchase-paid-amount-field" hidden><label for="purchase-paid-amount">Amount paid (₹)</label><input class="field" id="purchase-paid-amount" type="number" min="0.01" step="0.01" placeholder="0.00"></div><div class="form-field"><label for="purchase-payment-method">Payment method</label><select class="field" id="purchase-payment-method"><option>UPI</option><option>Cash</option><option>Bank transfer</option><option>Card</option><option>Other</option></select></div></div><div class="bill-total"><span>Purchase total<small>Outstanding after this payment: <b id="purchase-balance-preview">₹0</b></small></span><strong id="purchase-total">₹0</strong></div><div class="modal-actions"><button type="button" class="btn" data-close>Cancel</button><button class="btn btn-primary" type="submit">Save purchase &amp; update stock</button></div></form>`;document.querySelector('#purchase-form').addEventListener('submit',e=>{e.preventDefault();const supplier=document.querySelector('#purchase-supplier').value.trim(),invoiceNumber=document.querySelector('#purchase-invoice').value.trim(),date=document.querySelector('#purchase-date').value,rows=[...document.querySelectorAll('[data-purchase-line]')],lines=[];if(!supplier){toast('Enter the supplier name.');return;}for(const row of rows){const input=row.querySelector('[data-purchase-product]'),product=store.products.find(p=>p.id===input.dataset.productId&&p.name===input.value.trim()),quantity=Number(row.querySelector('[data-purchase-quantity]').value),purchaseRate=Number(row.querySelector('[data-purchase-rate]').value);if(!product){toast('Choose a product from inventory for each purchase line.');return;}if(!Number.isInteger(quantity)||quantity<1||!Number.isFinite(purchaseRate)||purchaseRate<=0){toast('Enter a valid whole quantity and purchase rate for each item.');return;}lines.push({productId:product.id,productName:product.name,category:product.category,quantity,purchaseRate,lineTotal:quantity*purchaseRate});}if(!lines.length){toast('Add at least one item to this purchase.');return;}const total=lines.reduce((sum,line)=>sum+line.lineTotal,0),mode=document.querySelector('#purchase-payment-status').value;let paidAmount=mode==='paid'?total:mode==='partial'?Number(document.querySelector('#purchase-paid-amount').value):0;if(!Number.isFinite(paidAmount)||paidAmount<0||paidAmount-total>0.001||(mode==='partial'&&paidAmount<=0)){toast('Enter a valid payment amount up to the purchase total.');return;}if(paidAmount>=total)paidAmount=total;const method=paidAmount>0?document.querySelector('#purchase-payment-method').value:'Credit',purchase={id:nextPurchaseId(),supplier,invoiceNumber,date,items:lines.reduce((sum,line)=>sum+line.quantity,0),lines,total,paidAmount,status:paidAmount>=total?'Paid':paidAmount>0?'Partially paid':'Pending',method};lines.forEach(line=>{const product=store.products.find(p=>p.id===line.productId);product.stock+=line.quantity;product.purchaseRate=line.purchaseRate;product.purchaseRateEstimated=false;product.supplier=supplier;product.lastPurchaseDate=date;product.lastPurchaseInvoice=invoiceNumber;});store.purchases.unshift(purchase);saveStore();closeModal();renderPage();toast(`Purchase ${purchase.id} saved and stock updated.`);});document.querySelector('#modal-backdrop').hidden=false;document.querySelector('.modal-close').focus();updatePurchaseTotal();}
function openPurchasePreview(purchaseId){const purchase=store.purchases.find(p=>p.id===purchaseId);if(!purchase)return;const host=document.querySelector('#modal-content'),payments=purchase.payments||[];host.innerHTML=`<h2 id="modal-title">Purchase details</h2><p class="modal-intro">${escapeHtml(purchase.supplier)} · ${escapeHtml(purchase.invoiceNumber||purchase.id)}</p><div class="purchase-detail-meta"><span>Purchase date<strong>${dateLabel(purchase.date)}</strong></span><span>Payment status<strong>${escapeHtml(purchase.status)}</strong></span><span>Balance due<strong>${money(purchaseDue(purchase))}</strong></span></div><div class="table-wrap"><table><thead><tr><th>PRODUCT</th><th>QTY</th><th>RATE</th><th>LINE TOTAL</th></tr></thead><tbody>${purchase.lines.map(line=>`<tr><td>${escapeHtml(line.productName)}</td><td>${line.quantity}</td><td>${money(line.purchaseRate)}</td><td>${money(line.lineTotal)}</td></tr>`).join('')}</tbody></table></div><div class="bill-total"><span>Total purchase cost<small>${money(purchase.paidAmount)} paid · ${money(purchaseDue(purchase))} balance</small></span><strong>${money(purchase.total)}</strong></div>${payments.length?`<div class="invoice-payment-history"><strong>Payment history</strong>${payments.map(payment=>`<div class="invoice-payment"><span>${dateLabel(payment.date)} · ${escapeHtml(payment.method)}</span><strong>${money(payment.amount)}</strong></div>`).join('')}</div>`:''}<div class="modal-actions">${purchaseDue(purchase)>0?`<button type="button" class="btn" data-purchase-payment="${escapeHtml(purchase.id)}">Record payment</button>`:''}<button type="button" class="btn btn-primary" data-close>Done</button></div>`;document.querySelector('#modal-backdrop').hidden=false;document.querySelector('.modal-close').focus();}
function openPurchasePaymentModal(purchaseId){const purchase=store.purchases.find(p=>p.id===purchaseId);if(!purchase||purchaseDue(purchase)<=0)return;const host=document.querySelector('#modal-content');host.innerHTML=`<h2 id="modal-title">Record supplier payment</h2><p class="modal-intro">Add a payment for ${escapeHtml(purchase.supplier)}. Remaining balance: <strong>${money(purchaseDue(purchase))}</strong></p><form id="purchase-payment-form"><div class="form-field"><label for="supplier-payment-amount">Amount paid (₹)</label><input class="field" id="supplier-payment-amount" type="number" min="0.01" max="${purchaseDue(purchase)}" step="0.01" required placeholder="0.00"></div><div class="form-grid"><div class="form-field"><label for="supplier-payment-date">Payment date</label><input class="field" id="supplier-payment-date" type="date" value="${localISODate()}" required></div><div class="form-field"><label for="supplier-payment-method">Payment method</label><select class="field" id="supplier-payment-method"><option>UPI</option><option>Cash</option><option>Bank transfer</option><option>Card</option><option>Other</option></select></div></div><div class="modal-actions"><button type="button" class="btn" data-close>Cancel</button><button type="submit" class="btn btn-primary">Save payment</button></div></form>`;document.querySelector('#purchase-payment-form').addEventListener('submit',e=>{e.preventDefault();const amount=Number(document.querySelector('#supplier-payment-amount').value),balance=purchaseDue(purchase),date=document.querySelector('#supplier-payment-date').value,method=document.querySelector('#supplier-payment-method').value;if(!Number.isFinite(amount)||amount<=0||amount-balance>0.001){toast('Enter a payment up to the remaining balance.');return;}purchase.paidAmount=Math.min(Number(purchase.paidAmount||0)+amount,Number(purchase.total));purchase.payments=purchase.payments||[];purchase.payments.push({date,amount,method});purchase.method=method;purchase.status=purchaseDue(purchase)<=0?'Paid':'Partially paid';saveStore();closeModal();renderPage();toast('Supplier payment recorded.');});document.querySelector('#modal-backdrop').hidden=false;document.querySelector('.modal-close').focus();}
function filterPurchases(){const query=document.querySelector('[data-purchase-search]')?.value.toLowerCase()||'',status=document.querySelector('#purchase-filter')?.value||'all';const list=store.purchases.filter(p=>(status==='all'||p.status===status)&&`${p.id} ${p.invoiceNumber||''} ${p.supplier}`.toLowerCase().includes(query));const table=document.querySelector('#purchases-table');if(table)table.innerHTML=purchaseRows(list);}
function inventoryPage(){const categories=[...new Set(store.products.map(p=>p.category))],costValue=store.products.reduce((sum,p)=>sum+Number(p.stock||0)*Number(p.purchaseRate||0),0),estimatedRates=store.products.filter(p=>p.purchaseRateEstimated).length;return `<div class="page-heading"><div><p class="eyebrow">PRODUCTS &amp; STOCK</p><h1>Inventory</h1><p>Track stock levels, supplier costs, and item margins.</p></div><div class="heading-actions"><button class="btn" data-action="export-products"><span class="btn-icon">↓</span> Export stock</button><button class="btn" data-action="new-purchase"><span class="btn-icon">↙</span> Receive stock</button><button class="btn btn-primary" data-action="add-product"><span class="btn-icon">＋</span> Add product</button></div></div><div class="metrics-grid"><article class="metric-card"><div class="metric-top"><span class="metric-label">Products in catalogue</span><span class="metric-icon blue">▦</span></div><div class="metric-value">${store.products.length}</div><div class="metric-foot"><span>Across ${categories.length} categories</span></div></article><article class="metric-card"><div class="metric-top"><span class="metric-label">Stock cost value</span><span class="metric-icon">₹</span></div><div class="metric-value">${money(costValue)}</div><div class="metric-foot"><span>${estimatedRates?`${estimatedRates} starting rates estimated`:'Using recorded purchase rates'}</span></div></article><article class="metric-card"><div class="metric-top"><span class="metric-label">Healthy stock</span><span class="metric-icon">✓</span></div><div class="metric-value">${store.products.filter(p=>p.stock>p.reorder).length}</div><div class="metric-foot"><span>Above reorder level</span></div></article><article class="metric-card"><div class="metric-top"><span class="metric-label">Needs restocking</span><span class="metric-icon pink">⚑</span></div><div class="metric-value">${lowStock().length}</div><div class="metric-foot"><span class="trend down">Review soon</span></div></article></div><div class="section-toolbar"><div class="toolbar-left"><h2>Product catalogue</h2><span class="muted-small">${store.products.length} products</span></div><div class="toolbar-left"><input class="inline-search" data-table-search placeholder="Search products…"><select class="filter-select" id="category-filter"><option value="all">All categories</option>${categories.map(c=>`<option>${escapeHtml(c)}</option>`).join('')}</select></div></div><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>PRODUCT</th><th>CATEGORY</th><th>SALE PRICE</th><th>PURCHASE RATE</th><th>UNIT MARGIN</th><th>IN STOCK</th><th>REORDER AT</th><th>SUPPLIER</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody id="products-table">${productRows(store.products)}</tbody></table></div></section>`;}function customersPage(){const total=store.customers.length,repeat=total?Math.round(store.customers.filter(c=>(Number(c.visits)||0)>1).length/total*100):0,spend=total?store.customers.reduce((sum,c)=>sum+Number(c.spent||0),0)/total:0,newThisMonth=store.customers.filter(c=>String(c.createdAt||'').startsWith(localISODate().slice(0,7))).length;return `<div class="page-heading"><div><p class="eyebrow">PEOPLE WHO KEEP YOU GOING</p><h1>Customers</h1><p>Get to know your regulars and the value they bring.</p></div><div class="heading-actions"><button class="btn" data-action="export-customers"><span class="btn-icon">↓</span> Export customers</button><button class="btn btn-primary" data-action="add-customer"><span class="btn-icon">＋</span> Add customer</button></div></div><div class="metrics-grid"><article class="metric-card"><div class="metric-top"><span class="metric-label">Customers</span><span class="metric-icon blue">♙</span></div><div class="metric-value">${total.toLocaleString('en-IN')}</div><div class="metric-foot"><span>Saved customer records</span></div></article><article class="metric-card"><div class="metric-top"><span class="metric-label">Repeat purchase rate</span><span class="metric-icon">↻</span></div><div class="metric-value">${repeat}%</div><div class="metric-foot"><span>Based on recorded visits</span></div></article><article class="metric-card"><div class="metric-top"><span class="metric-label">Average spend</span><span class="metric-icon orange">₹</span></div><div class="metric-value">${money(spend)}</div><div class="metric-foot"><span>Per saved customer</span></div></article><article class="metric-card"><div class="metric-top"><span class="metric-label">Added this month</span><span class="metric-icon pink">✦</span></div><div class="metric-value">${newThisMonth}</div><div class="metric-foot"><span>New customer records</span></div></article></div><div class="section-toolbar"><div class="toolbar-left"><h2>Your customers</h2><span class="muted-small">${total} saved</span></div><input class="inline-search" data-customer-search placeholder="Search customers…"></div><div class="customers-grid" id="customer-grid">${customerCards(store.customers)}</div>`;}function customerPendingAmount(customer){const phone=String(customer.phone||'').replace(/\D/g,'').slice(-10),name=String(customer.name||'').trim().toLowerCase();return store.bills.reduce((total,bill)=>{const billPhone=String(bill.phone||'').replace(/\D/g,'').slice(-10),matches=phone&&billPhone?phone===billPhone:String(bill.customer||'').trim().toLowerCase()===name;return matches?total+dueAmount(bill):total;},0);}
function customerCards(list){if(!list.length)return '<div class="panel empty-row">'+(store.customers.length?'No customers match your search.':'No customers yet. Add your first customer to get started.')+'</div>';const colors=['#eaf2fc','#f8eee5','#eeeaf5','#e7f1f1','#f6e9e9','#e8edf5'];return list.map((c,i)=>{const pending=customerPendingAmount(c),company=c.companyName?'<p>'+escapeHtml(c.companyName)+'</p>':'',email=c.email?'<p>'+escapeHtml(c.email)+'</p>':'';return '<article class="customer-card"><div class="customer-top"><span class="customer-avatar" style="background:'+colors[i%colors.length]+'">'+initials(c.name)+'</span><span class="customer-heading"><h3>'+escapeHtml(c.name)+'</h3>'+company+'<p>'+escapeHtml(c.phone)+'</p>'+email+'</span><span class="customer-actions"><button class="table-link" data-customer-edit="'+escapeHtml(c.id)+'">Edit</button><button class="table-link danger-link" data-customer-remove="'+escapeHtml(c.id)+'">Remove</button></span></div><div class="customer-stats"><span>VISITS<strong>'+c.visits+'</strong></span><span>LIFETIME SPEND<strong>'+money(c.spent)+'</strong></span><span>LIFETIME PENDING<strong class="'+(pending>0?'pending-value':'')+'">'+money(pending)+'</strong></span></div></article>';}).join('');}function reportsPage(){const sales=sumBills(store.bills),collected=sumCollected(store.bills),outstanding=store.bills.filter(b=>b.status==='Pending').reduce((sum,b)=>sum+dueAmount(b),0),categories=categoryBreakdown(),topCategory=categories[0];const insight=topCategory?`${escapeHtml(topCategory.name)} is your top category at ${Math.round(topCategory.value/sales*100)}% of recorded sales.`:'Sales insights will appear after your first bill.';return `<div class="page-heading"><div><p class="eyebrow">YOUR NUMBERS, CLEARLY</p><h1>Reports &amp; insights</h1><p>Reports are built from the bills you save in this workspace.</p></div><div class="heading-actions"><button class="btn btn-primary" data-action="export-bills"><span class="btn-icon">↓</span> Export sales report</button><button class="btn" data-export-analytics><span class="btn-icon">⇩</span> Export analysis data</button></div></div><div class="metrics-grid"><article class="metric-card"><div class="metric-top"><span class="metric-label">Recorded sales</span><span class="metric-icon">₹</span></div><div class="metric-value">${money(sales)}</div><div class="metric-foot"><span>${store.bills.length} bills</span></div></article><article class="metric-card"><div class="metric-top"><span class="metric-label">Collected</span><span class="metric-icon">✓</span></div><div class="metric-value">${money(collected)}</div><div class="metric-foot"><span>Payments recorded</span></div></article><article class="metric-card"><div class="metric-top"><span class="metric-label">Outstanding</span><span class="metric-icon orange">◷</span></div><div class="metric-value">${money(outstanding)}</div><div class="metric-foot"><span>Remaining balance</span></div></article><article class="metric-card"><div class="metric-top"><span class="metric-label">Customers</span><span class="metric-icon blue">♙</span></div><div class="metric-value">${store.customers.length}</div><div class="metric-foot"><span>Saved customer records</span></div></article></div><div class="report-grid"><article class="panel report-card"><span class="metric-icon">↗</span><h3>Sales summary</h3><p>Review saved invoices, payment status, and collected amounts.</p><button class="btn" data-action="export-bills">Download bills CSV <span>→</span></button></article><article class="panel report-card"><span class="metric-icon blue">▦</span><h3>Inventory report</h3><p>See products, stock value, reorder levels, and items that need attention.</p><button class="btn" data-action="export-products">Download inventory CSV <span>→</span></button></article><article class="panel report-card"><span class="metric-icon orange">♙</span><h3>Customer report</h3><p>Export the customer records you add, including company names and contact details.</p><button class="btn" data-action="export-customers">Download customers CSV <span>→</span></button></article><article class="panel report-card"><span class="metric-icon orange">↙</span><h3>Purchase report</h3><p>Review supplier invoices, purchase rates, and outstanding payables.</p><button class="btn" data-action="export-purchases">Download purchases CSV <span>→</span></button></article><article class="panel report-card"><span class="metric-icon blue">▦</span><h3>Google Sheets</h3><p>Saved changes sync automatically to separate Sheets tabs; you can also send a manual update.</p><div class="heading-actions"><button class="btn btn-primary" data-google-sheets-export>Export to Sheets</button><button class="btn" data-google-sheets-configure>Configure</button></div></article><article class="panel report-card"><span class="metric-icon pink">✦</span><h3>Sales insights</h3><p>${insight}</p><button class="btn" data-go="overview">Back to overview <span>→</span></button></article></div>`;}function settingsPage(){return `<div class="page-heading"><div><p class="eyebrow">MAKE IT YOURS</p><h1>Store settings</h1><p>Your workspace details and preferences.</p></div></div><section class="panel settings-card"><div class="settings-row"><span><strong>Store name</strong><small>${escapeHtml(store.profile.storeName||'Not set')}</small></span><button class="table-link" data-action="store-name">Edit</button></div><div class="settings-row"><span><strong>Store location</strong><small>${escapeHtml(store.profile.location||'Not set')}</small></span><button class="table-link" data-action="store-location">Edit</button></div><div class="settings-row"><span><strong>Currency</strong><small>Indian Rupee (₹)</small></span><span class="muted-small">INR</span></div><div class="settings-row"><span><strong>Low stock reminders</strong><small>Show a reminder when products reach their reorder level</small></span><span class="toggle"></span></div><div class="settings-row"><span><strong>Data storage</strong><small data-storage-mode>Checking local Python server</small></span><span class="settings-actions"><input type="file" id="workspace-import-file" accept=".json,application/json" hidden><button class="table-link" data-action="import-workspace">Import previous data</button><button class="table-link danger-link" data-action="reset-data">Reset data</button></span></div></section>`;}
function renderPage(){syncProfile();updateNavBadge();const views={overview:dashboard,billing:billingPage,inventory:inventoryPage,purchases:purchasesPage,customers:customersPage,reports:reportsPage,settings:settingsPage};document.querySelector('#page-content').innerHTML=(views[currentPage]||dashboard)();const storageMode=document.querySelector('[data-storage-mode]');if(storageMode)storageMode.textContent=pythonBackendConnected?'Python + SQLite with browser cache':'Browser cache · checking local Python server';if(currentPage==='overview'){drawChart();if(pythonBackendConnected)loadPythonSuggestions();}if(currentPage==='billing')filterBills();if(currentPage==='inventory')filterProducts();if(currentPage==='purchases')filterPurchases();if(currentPage==='customers')filterCustomers();}

function drawChart(){const svg=document.querySelector('#sales-chart');if(!svg)return;const data=salesChartData(),w=700,h=190,p={l:34,r:14,t:12,b:25},cw=w-p.l-p.r,ch=h-p.t-p.b,max=Math.max(1,...data.values,...data.prev)*1.18,grid=[0,.25,.5,.75,1];const x=i=>p.l+(data.values.length===1?cw/2:i*cw/(data.values.length-1));const y=v=>p.t+ch-(v/max)*ch;const path=arr=>arr.map((v,i)=>`${i?'L':'M'} ${x(i).toFixed(1)} ${y(v).toFixed(1)}`).join(' ');let markup='';grid.forEach(g=>{const yy=p.t+ch-g*ch,label=max*g>=1000?`${(max*g/1000).toFixed(0)}k`:Math.round(max*g);markup+=`<line x1="${p.l}" y1="${yy}" x2="${w-p.r}" y2="${yy}" stroke="#e8eff7" stroke-width="1"/><text x="${p.l-8}" y="${yy+3}" text-anchor="end" fill="#9aa9bd" font-size="8">${label}</text>`;});data.labels.forEach((label,i)=>markup+=`<text x="${x(i)}" y="${h-5}" text-anchor="middle" fill="#95a3b7" font-size="8">${label}</text>`);const previous=path(data.prev),current=path(data.values),area=`${current} L ${x(data.values.length-1)} ${p.t+ch} L ${x(0)} ${p.t+ch} Z`;markup+=`<path d="${previous}" fill="none" stroke="#dce8f5" stroke-width="2" stroke-dasharray="4 5" stroke-linecap="round"/><path d="${area}" fill="url(#chartFill)"/><defs><linearGradient id="chartFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#3b82cb" stop-opacity=".2"/><stop offset="1" stop-color="#3b82cb" stop-opacity="0"/></linearGradient></defs><path d="${current}" fill="none" stroke="#1e68b4" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>`;data.values.forEach((value,i)=>markup+=`<circle class="chart-point" data-index="${i}" cx="${x(i)}" cy="${y(value)}" r="3.2" fill="#fff" stroke="#1e68b4" stroke-width="2"/>`);if(!data.values.some(value=>value>0))markup+=`<text x="${w/2}" y="${h/2}" text-anchor="middle" fill="#9daabd" font-size="10">No sales recorded for this period</text>`;svg.innerHTML=markup;document.querySelector('#chart-total').innerHTML=`${data.total} <small>${data.change}</small>`;svg.querySelectorAll('.chart-point').forEach(point=>{point.addEventListener('mouseenter',()=>{const index=Number(point.dataset.index),tip=document.querySelector('#chart-tooltip'),rect=svg.getBoundingClientRect();tip.textContent=`${data.labels[index]} · ${money(data.values[index])}`;tip.style.left=`${(Number(point.getAttribute('cx'))/700)*rect.width}px`;tip.style.top=`${(Number(point.getAttribute('cy'))/190)*rect.height}px`;tip.style.display='block';});point.addEventListener('mouseleave',()=>document.querySelector('#chart-tooltip').style.display='none');});}function billLineMarkup(){return `<div class="bill-line" data-bill-line><div class="form-field bill-product-field"><label>Product</label><input class="field" data-bill-product list="bill-product-options" autocomplete="off" placeholder="Search products…"><small class="line-hint">Search and choose a product</small></div><div class="form-field bill-qty-field"><label>Qty</label><input class="field" data-bill-quantity type="number" min="1" step="1" value="1"></div><button type="button" class="remove-line" data-remove-bill-line aria-label="Remove item">×</button></div>`;}
function addBillLine(){const list=document.querySelector('#bill-lines');if(!list)return;list.insertAdjacentHTML('beforeend',billLineMarkup());list.querySelector('.bill-line:last-child [data-bill-product]').focus();updateBillTotal();}
function updateBillTotal(){const rows=[...document.querySelectorAll('[data-bill-line]')];let total=0,quantity=0;rows.forEach(row=>{const input=row.querySelector('[data-bill-product]'),qty=Number(row.querySelector('[data-bill-quantity]').value)||0,product=store.products.find(p=>p.id===input.dataset.productId);if(product){total+=product.price*qty;quantity+=qty;}});const amount=document.querySelector('#bill-preview'),count=document.querySelector('#bill-item-count'),paid=document.querySelector('#bill-paid-amount');if(amount){amount.textContent=money(total);amount.dataset.total=String(total);}if(count)count.textContent=`${rows.length} line${rows.length===1?'':'s'} · ${quantity} item${quantity===1?'':'s'}`;if(paid){paid.max=total.toFixed(2);if(document.querySelector('#bill-payment-status')?.value==='paid')paid.value=total.toFixed(2);else if(document.querySelector('#bill-payment-status')?.value==='partial'&&Number(paid.value)>total)paid.value=total.toFixed(2);}}
function syncBillPaymentFields(clearPartial=false){const status=document.querySelector('#bill-payment-status'),fields=document.querySelector('#bill-payment-fields'),amount=document.querySelector('#bill-paid-amount'),note=document.querySelector('#bill-payment-note');if(!status||!fields||!amount)return;const mode=status.value;fields.hidden=mode==='pending';amount.disabled=mode==='paid'||mode==='pending';if(mode==='paid'){amount.value=(Number(document.querySelector('#bill-preview')?.dataset.total)||0).toFixed(2);if(note)note.textContent='The full bill total will be recorded as paid.';}else if(mode==='partial'){if(clearPartial)amount.value='';if(note)note.textContent='Enter the amount received now. The remaining amount will stay pending.';}else{amount.value='0';if(note)note.textContent='The full bill amount will remain pending.';}}function updateBillCustomerSuggestions(){const input=document.querySelector('#bill-customer'),menu=document.querySelector('#bill-customer-suggestions');if(!input||!menu)return;const query=input.value.trim().toLowerCase();if(!query){menu.hidden=true;return;}const matches=store.customers.filter(c=>c.name.toLowerCase().includes(query)).slice(0,6),exact=store.customers.some(c=>c.name.trim().toLowerCase()===query);let html=matches.map(c=>`<button type="button" class="suggestion-option" data-select-customer="${escapeHtml(c.id)}"><span>${escapeHtml(c.name)}</span><small>${escapeHtml(c.phone)}</small></button>`).join('');if(!exact)html+=`<button type="button" class="suggestion-option new-option" data-new-customer-choice><span>＋ Add “${escapeHtml(input.value.trim())}” as a new customer</span></button>`;menu.innerHTML=html;menu.hidden=!html;}
function chooseBillingCustomer(customerId){const customer=store.customers.find(c=>c.id===customerId);if(!customer)return;const input=document.querySelector('#bill-customer'),phoneField=document.querySelector('#bill-new-customer-field'),note=document.querySelector('#bill-customer-note');input.value=customer.name;input.dataset.customerId=customer.id;input.dataset.newCustomer='false';phoneField.hidden=true;document.querySelector('#bill-customer-phone').required=false;document.querySelector('#bill-customer-phone').value=customer.phone||'';document.querySelector('#bill-customer-company').value=customer.companyName||'';note.textContent=`Existing customer · ${customer.phone||'no phone saved'}`;document.querySelector('#bill-customer-suggestions').hidden=true;}
function chooseNewBillingCustomer(){const input=document.querySelector('#bill-customer'),phoneField=document.querySelector('#bill-new-customer-field'),note=document.querySelector('#bill-customer-note');if(!input.value.trim())return;input.dataset.customerId='';input.dataset.newCustomer='true';phoneField.hidden=false;const phone=document.querySelector('#bill-customer-phone');phone.required=true;note.textContent='This customer will be added to your records when you save the bill.';document.querySelector('#bill-customer-suggestions').hidden=true;phone.focus();}function nextBillId(){const used=new Set(store.bills.map(b=>b.id));let number=1;while(used.has(`INV-${String(number).padStart(4,'0')}`))number++;return `INV-${String(number).padStart(4,'0')}`;}function openBillModalContent(host){host.innerHTML=`<h2 id="modal-title">Create a bill</h2><p class="modal-intro">Find a customer, add products, and choose how much they are paying now.</p><form id="bill-form"><div class="form-field customer-search-field"><label for="bill-customer">Customer name</label><input class="field" id="bill-customer" autocomplete="off" required placeholder="Search customers or type a new name"><div class="suggestion-menu" id="bill-customer-suggestions" hidden></div><small class="form-note" id="bill-customer-note">Choose an existing customer or add a new one.</small></div><div class="form-grid"><div class="form-field"><label for="bill-customer-company">Customer company <span class="muted-small">(optional)</span></label><input class="field" id="bill-customer-company" placeholder="Company name"></div><div class="form-field" id="bill-new-customer-field" hidden><label for="bill-customer-phone">New customer phone</label><input class="field" id="bill-customer-phone" type="tel" placeholder="e.g. 98765 43210"></div></div><div class="bill-lines-heading"><strong>Items</strong><button type="button" class="table-link" data-add-bill-line>＋ Add another item</button></div><div id="bill-lines"></div><datalist id="bill-product-options">${store.products.map(p=>`<option value="${escapeHtml(p.name)}" label="${money(p.price)} · ${p.stock} in stock"></option>`).join('')}</datalist><div class="form-field"><label for="bill-payment-status">Payment status</label><select class="field" id="bill-payment-status"><option value="paid">Paid in full</option><option value="partial">Partially paid now</option><option value="pending">Leave payment pending</option></select></div><div id="bill-payment-fields" class="form-grid"><div class="form-field"><label for="bill-paid-amount">Amount received (₹)</label><input class="field" id="bill-paid-amount" type="number" min="0.01" step="0.01" required disabled></div><div class="form-field"><label for="bill-payment-method">Payment method</label><select class="field" id="bill-payment-method"><option>UPI</option><option>Cash</option><option>Card</option><option>Bank transfer</option></select></div></div><p class="form-note" id="bill-payment-note">The full bill total will be recorded as paid.</p><div class="bill-total"><span>Bill total <small id="bill-item-count">0 items</small></span><strong id="bill-preview" data-total="0">${money(0)}</strong></div><div class="modal-actions bill-save-actions"><button type="button" class="btn" data-close>Cancel</button><button type="submit" class="btn btn-primary" data-after-save="preview">Save bill</button><button type="submit" class="btn" data-after-save="print">Save &amp; Print</button><button type="submit" class="btn" data-after-save="whatsapp">Save &amp; WhatsApp</button><button type="submit" class="btn" data-after-save="whatsapp-pdf">Save &amp; Share PDF</button></div></form>`;document.querySelector('#bill-lines').insertAdjacentHTML('beforeend',billLineMarkup());updateBillTotal();syncBillPaymentFields();document.querySelector('#bill-payment-status').addEventListener('change',()=>syncBillPaymentFields(true));document.querySelector('#bill-form').addEventListener('submit',e=>{e.preventDefault();const afterSave=e.submitter?.dataset.afterSave||'preview',customerInput=document.querySelector('#bill-customer'),typedName=customerInput.value.trim(),selectedId=customerInput.dataset.customerId||'',selectedCustomer=store.customers.find(c=>c.id===selectedId),customer=selectedCustomer||store.customers.find(c=>c.name.trim().toLowerCase()===typedName.toLowerCase());const rows=[...document.querySelectorAll('[data-bill-line]')],items=[];for(const row of rows){const input=row.querySelector('[data-bill-product]'),product=store.products.find(p=>p.id===input.dataset.productId),qty=Number(row.querySelector('[data-bill-quantity]').value);if(!product){toast('Choose a product for every bill line.');return;}if(!Number.isInteger(qty)||qty<1){toast('Enter a whole number quantity for each product.');return;}items.push({product,quantity:qty,productId:product.id,productName:product.name,category:product.category,unitPrice:product.price,lineTotal:product.price*qty});}if(!items.length){toast('Add at least one product to this bill.');return;}const quantities=new Map();items.forEach(item=>quantities.set(item.productId,(quantities.get(item.productId)||0)+item.quantity));for(const [productId,qty] of quantities){const product=store.products.find(p=>p.id===productId);if(product.stock<qty){toast(`Only ${product.stock} ${product.name} available in stock.`);return;}}const total=items.reduce((sum,item)=>sum+item.lineTotal,0),mode=document.querySelector('#bill-payment-status').value;let paidAmount=mode==='pending'?0:mode==='paid'?total:Number(document.querySelector('#bill-paid-amount').value);if(!Number.isFinite(paidAmount)||paidAmount<0||paidAmount-total>0.001||(mode==='partial'&&paidAmount<=0)){toast('Enter a valid payment amount up to the bill total.');return;}if(paidAmount>=total)paidAmount=total;let billCustomer=customer,companyName=document.querySelector('#bill-customer-company').value.trim();if(!billCustomer){if(customerInput.dataset.newCustomer!=='true'){toast('Choose an existing customer or select the new customer option.');updateBillCustomerSuggestions();return;}const phone=document.querySelector('#bill-customer-phone').value.trim();if(!phone){toast('Enter the new customer’s phone number.');return;}if(store.customers.some(c=>c.phone.trim()===phone)){toast('That phone number is already saved. Select the existing customer instead.');return;}billCustomer={id:nextCustomerId(),name:typedName,phone,email:'',companyName,createdAt:localISODate(),visits:0,spent:0};store.customers.unshift(billCustomer);}else if(companyName)billCustomer.companyName=companyName;companyName=companyName||billCustomer.companyName||'';const today=localISODate(),method=paidAmount===0?'Credit':document.querySelector('#bill-payment-method').value;quantities.forEach((qty,productId)=>{const product=store.products.find(p=>p.id===productId);product.stock-=qty;});billCustomer.visits=(Number(billCustomer.visits)||0)+1;billCustomer.spent=(Number(billCustomer.spent)||0)+total;const createdBill={id:nextBillId(),customerId:billCustomer.id,customer:billCustomer.name,customerCompanyName:companyName,phone:billCustomer.phone||'—',date:today,items:items.reduce((sum,item)=>sum+item.quantity,0),lines:items.map(({product,...line})=>line),total,status:paidAmount>=total?'Paid':'Pending',method,paidAmount,payments:paidAmount?[{date:today,amount:paidAmount,method}]:[]};store.bills.unshift(createdBill);saveStore();closeModal();renderPage();openBillPreview(createdBill.id);toast('Bill saved. Preview is ready to print or share.');if(afterSave==='print')window.print();if(afterSave==='whatsapp')window.open(whatsappBillUrl(createdBill),'_blank','noopener,noreferrer');if(afterSave==='whatsapp-pdf')shareBillPdf(createdBill.id);});}function openModal(type){const host=document.querySelector('#modal-content');if(type==='bill'){openBillModalContent(host);}
else if(type==='product'){host.innerHTML=`<h2 id="modal-title">Add a product</h2><p class="modal-intro">Add an item with its purchase cost to track margins and stock value.</p><form id="product-form"><div class="form-field"><label for="product-name">Product name</label><input class="field" id="product-name" required placeholder="e.g. Filter Coffee 500g"></div><div class="form-grid"><div class="form-field"><label for="product-category">Category</label><input class="field" id="product-category" required placeholder="e.g. Beverages"></div><div class="form-field"><label for="product-price">Selling price (₹)</label><input class="field" id="product-price" type="number" min="0.01" step="0.01" required placeholder="0.00"></div><div class="form-field"><label for="product-purchase-rate">Purchase rate (₹)</label><input class="field" id="product-purchase-rate" type="number" min="0.01" step="0.01" required placeholder="0.00"></div><div class="form-field"><label for="product-supplier">Supplier <span class="muted-small">(optional)</span></label><input class="field" id="product-supplier" placeholder="Supplier name"></div><div class="form-field"><label for="product-stock">Opening stock</label><input class="field" id="product-stock" type="number" min="0" required value="0"></div><div class="form-field"><label for="product-reorder">Restock reminder at</label><input class="field" id="product-reorder" type="number" min="0" required value="10"></div></div><div class="modal-actions"><button type="button" class="btn" data-close>Cancel</button><button class="btn btn-primary" type="submit">Add product</button></div></form>`;document.querySelector('#product-form').addEventListener('submit',e=>{e.preventDefault();const name=document.querySelector('#product-name').value.trim();store.products.unshift({id:nextProductId(),name,category:document.querySelector('#product-category').value.trim(),price:Number(document.querySelector('#product-price').value),purchaseRate:Number(document.querySelector('#product-purchase-rate').value),purchaseRateEstimated:false,supplier:document.querySelector('#product-supplier').value.trim()||'Not specified',lastPurchaseDate:'',stock:Number(document.querySelector('#product-stock').value),reorder:Number(document.querySelector('#product-reorder').value),emoji:'📦'});saveStore();closeModal();renderPage();toast(`${name} added to inventory.`);});}
document.querySelector('#modal-backdrop').hidden=false;document.querySelector('.modal-close').focus();}function openAdjustModal(id){const product=store.products.find(p=>p.id===id);if(!product)return;const host=document.querySelector('#modal-content');host.innerHTML=`<h2 id="modal-title">Adjust stock</h2><p class="modal-intro">Update the stock count for ${escapeHtml(product.name)}.</p><div class="bill-total"><span>Current stock</span><strong>${product.stock} units</strong></div><form id="adjust-form"><div class="form-field"><label for="stock-change">Units to add or remove</label><input class="field" id="stock-change" type="number" step="1" required placeholder="e.g. 12 or -3"><p class="form-note">Use a positive number for incoming stock and a negative number for stock corrections.</p></div><div class="modal-actions"><button type="button" class="btn" data-close>Cancel</button><button class="btn btn-primary" type="submit">Save adjustment</button></div></form>`;document.querySelector('#adjust-form').addEventListener('submit',e=>{e.preventDefault();const change=Number(document.querySelector('#stock-change').value);if(!Number.isInteger(change)||product.stock+change<0){toast('Stock must remain at zero or above.');return;}product.stock+=change;saveStore();closeModal();renderPage();toast('Stock level updated.');});document.querySelector('#modal-backdrop').hidden=false;document.querySelector('.modal-close').focus();}
function nextProductId(){const used=new Set(store.products.map(p=>p.id));let number=1001;while(used.has(`P-${number}`))number++;return `P-${number}`;}
function nextCustomerId(){const used=new Set(store.customers.map(c=>c.id));let number=1001;while(used.has(`C-${number}`))number++;return `C-${number}`;}
function openCustomerModal(customerId=''){const customer=customerId?store.customers.find(c=>c.id===customerId):null;if(customerId&&!customer)return;const host=document.querySelector('#modal-content');host.innerHTML=`<h2 id="modal-title">${customer?'Edit customer':'Add customer'}</h2><p class="modal-intro">${customer?'Update this customer’s details.':'Add a customer to your store records.'}</p><form id="customer-form"><div class="form-field"><label for="customer-name">Customer name</label><input class="field" id="customer-name" required value="${escapeHtml(customer?.name||'')}" placeholder="e.g. Priya Sharma"></div><div class="form-field"><label for="customer-company">Company name <span class="muted-small">(optional)</span></label><input class="field" id="customer-company" value="${escapeHtml(customer?.companyName||'')}" placeholder="Company or business name"></div><div class="form-field"><label for="customer-phone">Phone number</label><input class="field" id="customer-phone" type="tel" required value="${escapeHtml(customer?.phone||'')}" placeholder="e.g. 98765 43210"></div><div class="form-field"><label for="customer-email">Email <span class="muted-small">(optional)</span></label><input class="field" id="customer-email" type="email" value="${escapeHtml(customer?.email||'')}" placeholder="name@example.com"></div><div class="modal-actions"><button type="button" class="btn" data-close>Cancel</button><button class="btn btn-primary" type="submit">${customer?'Save changes':'Add customer'}</button></div></form>`;document.querySelector('#customer-form').addEventListener('submit',e=>{e.preventDefault();const name=document.querySelector('#customer-name').value.trim(),companyName=document.querySelector('#customer-company').value.trim(),phone=document.querySelector('#customer-phone').value.trim(),email=document.querySelector('#customer-email').value.trim();if(store.customers.some(c=>c.id!==customerId&&c.phone.trim()===phone)){toast('A customer with that phone number already exists.');return;}if(customer){customer.name=name;customer.companyName=companyName;customer.phone=phone;customer.email=email;}else store.customers.unshift({id:nextCustomerId(),name,companyName,phone,email,createdAt:localISODate(),visits:0,spent:0});saveStore();closeModal();renderPage();toast(customer?'Customer updated.':'Customer added.');});document.querySelector('#modal-backdrop').hidden=false;document.querySelector('.modal-close').focus();}function openProductEditModal(productId){const product=store.products.find(p=>p.id===productId);if(!product)return;const host=document.querySelector('#modal-content');host.innerHTML=`<h2 id="modal-title">Edit product details</h2><p class="modal-intro">Update pricing, supplier cost, and current stock.</p><form id="product-edit-form"><div class="form-field"><label for="edit-product-name">Product name</label><input class="field" id="edit-product-name" required value="${escapeHtml(product.name)}"></div><div class="form-grid"><div class="form-field"><label for="edit-product-category">Category</label><input class="field" id="edit-product-category" required value="${escapeHtml(product.category)}"></div><div class="form-field"><label for="edit-product-price">Selling price (₹)</label><input class="field" id="edit-product-price" type="number" min="0.01" step="0.01" required value="${product.price}"></div><div class="form-field"><label for="edit-product-purchase-rate">Purchase rate (₹)</label><input class="field" id="edit-product-purchase-rate" type="number" min="0.01" step="0.01" required value="${Number(product.purchaseRate||0)}"></div><div class="form-field"><label for="edit-product-supplier">Supplier</label><input class="field" id="edit-product-supplier" value="${escapeHtml(product.supplier||'')}"></div><div class="form-field"><label for="edit-product-stock">Current stock</label><input class="field" id="edit-product-stock" type="number" min="0" step="1" required value="${product.stock}"></div><div class="form-field"><label for="edit-product-reorder">Restock reminder at</label><input class="field" id="edit-product-reorder" type="number" min="0" step="1" required value="${product.reorder}"></div><div class="form-field full"><label for="edit-product-emoji">Product icon</label><input class="field" id="edit-product-emoji" maxlength="8" value="${escapeHtml(product.emoji||'📦')}" placeholder="📦"></div></div><div class="modal-actions"><button type="button" class="btn" data-close>Cancel</button><button class="btn btn-primary" type="submit">Save changes</button></div></form>`;document.querySelector('#product-edit-form').addEventListener('submit',e=>{e.preventDefault();product.name=document.querySelector('#edit-product-name').value.trim();product.category=document.querySelector('#edit-product-category').value.trim();product.price=Number(document.querySelector('#edit-product-price').value);product.purchaseRate=Number(document.querySelector('#edit-product-purchase-rate').value);product.purchaseRateEstimated=false;product.supplier=document.querySelector('#edit-product-supplier').value.trim()||'Not specified';product.stock=Number(document.querySelector('#edit-product-stock').value);product.reorder=Number(document.querySelector('#edit-product-reorder').value);product.emoji=document.querySelector('#edit-product-emoji').value.trim()||'📦';saveStore();closeModal();renderPage();toast('Product details updated.');});document.querySelector('#modal-backdrop').hidden=false;document.querySelector('.modal-close').focus();}function whatsappBillUrl(bill){const rawPhone=String(bill.phone||'').replace(/\D/g,''),phone=rawPhone.length===10?`91${rawPhone}`:rawPhone.length===11&&rawPhone.startsWith('0')?`91${rawPhone.slice(1)}`:rawPhone,lines=[`*${store.profile.storeName}*`,`Invoice: ${bill.id}`,`Date: ${dateLabel(bill.date)}`,`Customer: ${bill.customer}${bill.customerCompanyName?` · ${bill.customerCompanyName}`:''}`,''];if(bill.lines?.length)bill.lines.forEach(line=>lines.push(`${line.productName} × ${line.quantity} @ ${money(line.unitPrice)} = ${money(line.lineTotal)}`));else lines.push(`${bill.items} items`);lines.push('',`Bill total: ${money(bill.total)}`,`Paid: ${money(bill.paidAmount)}`,`Balance due: ${money(dueAmount(bill))}`,`Status: ${bill.status}`,'',`Thank you for shopping with ${store.profile.storeName}.`,`Generated with ${APP_NAME} · ${APP_TAGLINE}`);return `https://wa.me/${phone}?text=${encodeURIComponent(lines.join('\n'))}`;}
function fitPdfText(ctx,value,maxWidth){let text=String(value||'');if(ctx.measureText(text).width<=maxWidth)return text;while(text.length>2&&ctx.measureText(`${text}…`).width>maxWidth)text=text.slice(0,-1);return `${text}…`;}
function drawBillPdfPage(bill,items,pageIndex,pageCount){const canvas=document.createElement('canvas');canvas.width=1588;canvas.height=2246;const ctx=canvas.getContext('2d');ctx.scale(2,2);const width=794,height=1123,margin=52,first=pageIndex===0,last=pageIndex===pageCount-1;ctx.fillStyle='#fff';ctx.fillRect(0,0,width,height);if(appLogoImage.complete&&appLogoImage.naturalWidth){ctx.drawImage(appLogoImage,margin,28,94,94);}else{ctx.fillStyle='#eaf2fc';ctx.fillRect(margin,28,94,94);ctx.fillStyle='#143d75';ctx.font='700 25px Arial,sans-serif';ctx.textAlign='center';ctx.fillText('BP',margin+47,84);ctx.textAlign='left';}ctx.fillStyle='#1b324d';ctx.font='700 18px Arial,sans-serif';ctx.fillText(fitPdfText(ctx,store.profile.storeName,310),margin+106,67);ctx.fillStyle='#73849b';ctx.font='11px Arial,sans-serif';ctx.fillText(fitPdfText(ctx,`${store.profile.businessSector||'Retail'} · ${store.profile.location||''}`,310),margin+106,88);ctx.textAlign='right';ctx.fillStyle='#1b62a6';ctx.font='700 21px Arial,sans-serif';ctx.fillText('INVOICE',width-margin,68);ctx.fillStyle='#7e8fa7';ctx.font='10px Arial,sans-serif';ctx.fillText(`${bill.id} · ${dateLabel(bill.date)}`,width-margin,88);ctx.textAlign='left';ctx.strokeStyle='#e2ebf6';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(margin,137);ctx.lineTo(width-margin,137);ctx.stroke();if(first){const info=[['INVOICE NUMBER',bill.id],['DATE',dateLabel(bill.date)],['PAYMENT STATUS',bill.status]];info.forEach((part,index)=>{const x=margin+index*230;ctx.fillStyle='#f6f9fd';ctx.fillRect(x,154,214,56);ctx.fillStyle='#8495ad';ctx.font='9px Arial,sans-serif';ctx.fillText(part[0],x+12,174);ctx.fillStyle='#344c6b';ctx.font='700 12px Arial,sans-serif';ctx.fillText(fitPdfText(ctx,part[1],188),x+12,194);});ctx.fillStyle='#8495ad';ctx.font='700 9px Arial,sans-serif';ctx.fillText('BILLED TO',margin,239);ctx.fillStyle='#1f3a5d';ctx.font='700 15px Arial,sans-serif';ctx.fillText(fitPdfText(ctx,bill.customer,450),margin,261);ctx.fillStyle='#6b7c91';ctx.font='11px Arial,sans-serif';if(bill.customerCompanyName)ctx.fillText(fitPdfText(ctx,bill.customerCompanyName,450),margin,280);ctx.fillText(fitPdfText(ctx,bill.phone||'',450),margin,bill.customerCompanyName?298:280);}else{ctx.fillStyle='#6b7c91';ctx.font='11px Arial,sans-serif';ctx.fillText(`Invoice ${bill.id} · continued`,margin,177);}const tableY=first?316:210,rowHeight=38;ctx.fillStyle='#edf4fc';ctx.fillRect(margin,tableY,width-margin*2,38);ctx.fillStyle='#586d89';ctx.font='700 9px Arial,sans-serif';ctx.fillText('ITEM',margin+12,tableY+24);ctx.textAlign='right';ctx.fillText('QTY',540,tableY+24);ctx.fillText('PRICE',642,tableY+24);ctx.fillText('AMOUNT',width-margin-12,tableY+24);ctx.textAlign='left';items.forEach((item,index)=>{const y=tableY+38+index*rowHeight;ctx.fillStyle=index%2?'#fbfcff':'#fff';ctx.fillRect(margin,y,width-margin*2,rowHeight);ctx.fillStyle='#314b6b';ctx.font='11px Arial,sans-serif';ctx.fillText(fitPdfText(ctx,item.productName,390),margin+12,y+24);ctx.textAlign='right';ctx.fillText(String(item.quantity),540,y+24);ctx.fillText(money(item.unitPrice),642,y+24);ctx.fillText(money(item.lineTotal),width-margin-12,y+24);ctx.textAlign='left';ctx.strokeStyle='#e7edf4';ctx.beginPath();ctx.moveTo(margin,y+rowHeight);ctx.lineTo(width-margin,y+rowHeight);ctx.stroke();});const afterTable=tableY+38+items.length*rowHeight;if(last){const totalX=width-margin-286;let y=afterTable+22;ctx.fillStyle='#6b7c91';ctx.font='11px Arial,sans-serif';ctx.fillText('Bill total',totalX,y);ctx.textAlign='right';ctx.fillStyle='#314b6b';ctx.font='700 11px Arial,sans-serif';ctx.fillText(money(bill.total),width-margin-12,y);y+=25;ctx.textAlign='left';ctx.fillStyle='#6b7c91';ctx.font='11px Arial,sans-serif';ctx.fillText('Paid',totalX,y);ctx.textAlign='right';ctx.fillStyle='#314b6b';ctx.font='700 11px Arial,sans-serif';ctx.fillText(money(bill.paidAmount),width-margin-12,y);y+=14;ctx.fillStyle='#eaf2fc';ctx.fillRect(totalX-10,y,width-margin-totalX+10,40);ctx.textAlign='left';ctx.fillStyle='#175d9f';ctx.font='700 10px Arial,sans-serif';ctx.fillText(dueAmount(bill)>0?'BALANCE DUE':'PAYMENT COMPLETE',totalX,y+25);ctx.textAlign='right';ctx.font='700 14px Arial,sans-serif';ctx.fillText(money(dueAmount(bill)),width-margin-12,y+26);ctx.textAlign='left';}else{ctx.fillStyle='#7e8fa7';ctx.font='10px Arial,sans-serif';ctx.fillText('Items continue on the next page.',margin,afterTable+28);}ctx.fillStyle=dueAmount(bill)>0?'#fff3e6':'#edf4fc';ctx.fillRect(margin,976,width-margin*2,48);ctx.fillStyle=dueAmount(bill)>0?'#a96728':'#205e9f';ctx.font='700 10px Arial,sans-serif';ctx.fillText(dueAmount(bill)>0?'AMOUNT PENDING':'PAYMENT COMPLETE',margin+14,1005);ctx.textAlign='right';ctx.font='700 16px Arial,sans-serif';ctx.fillText(money(dueAmount(bill)),width-margin-14,1007);ctx.textAlign='center';ctx.fillStyle='#8293aa';ctx.font='10px Arial,sans-serif';ctx.fillText('Thank you for shopping with us.',width/2,1062);ctx.textAlign='right';ctx.fillText(`Page ${pageIndex+1} of ${pageCount}`,width-margin,1090);return canvas;}
function createBillPdfBlob(bill){const sourceLines=bill.lines?.length?bill.lines:[{productName:`${bill.items} items`,quantity:bill.items,unitPrice:0,lineTotal:bill.total}],pageSize=12,pageCount=Math.max(1,Math.ceil(sourceLines.length/pageSize)),canvases=[];for(let index=0;index<pageCount;index++)canvases.push(drawBillPdfPage(bill,sourceLines.slice(index*pageSize,(index+1)*pageSize),index,pageCount));const images=canvases.map(canvas=>{const raw=atob(canvas.toDataURL('image/jpeg',0.94).split(',')[1]),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);return bytes;});const encoder=new TextEncoder(),chunks=[];let offset=0;const offsets=[];const append=chunk=>{const bytes=typeof chunk==='string'?encoder.encode(chunk):chunk;chunks.push(bytes);offset+=bytes.length;};append('%PDF-1.4\n');const object=(id,body)=>{offsets[id]=offset;append(`${id} 0 obj\n${body}\nendobj\n`);};const maxId=2+pageCount*3;object(1,'<< /Type /Catalog /Pages 2 0 R >>');const pageRefs=canvases.map((_,index)=>`${3+index*3} 0 R`).join(' ');object(2,`<< /Type /Pages /Kids [${pageRefs}] /Count ${pageCount} >>`);canvases.forEach((canvas,index)=>{const pageId=3+index*3,imageId=pageId+1,contentId=pageId+2,image=images[index],content=encoder.encode('q 595 0 0 842 0 0 cm /Im0 Do Q');object(pageId,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /XObject << /Im0 ${imageId} 0 R >> >> /Contents ${contentId} 0 R >>`);offsets[imageId]=offset;append(`${imageId} 0 obj\n<< /Type /XObject /Subtype /Image /Width ${canvas.width} /Height ${canvas.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${image.length} >>\nstream\n`);append(image);append('\nendstream\nendobj\n');object(contentId,`<< /Length ${content.length} >>\nstream\n${new TextDecoder().decode(content)}\nendstream`);});const xrefOffset=offset;append(`xref\n0 ${maxId+1}\n0000000000 65535 f \n`);for(let id=1;id<=maxId;id++)append(`${String(offsets[id]).padStart(10,'0')} 00000 n \n`);append(`trailer\n<< /Size ${maxId+1} /Root 1 0 R >>\nstartxref\n${xrefOffset}\n%%EOF`);return new Blob(chunks,{type:'application/pdf'});}
function downloadBillPdf(blob,bill){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`${bill.id}.pdf`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function shareBillPdf(billId){const bill=store.bills.find(item=>item.id===billId);if(!bill)return;try{if(!appLogoImage.complete&&appLogoImage.decode){try{await appLogoImage.decode();}catch(error){}}const blob=createBillPdfBlob(bill),file=typeof File!=='undefined'?new File([blob],`${bill.id}.pdf`,{type:'application/pdf'}):null;if(file&&navigator.share&&navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:`${APP_NAME} bill ${bill.id}`,text:`${store.profile.storeName} · ${bill.id} · Balance due ${money(dueAmount(bill))}`});return;}catch(error){if(error.name==='AbortError')return;}}downloadBillPdf(blob,bill);window.open(whatsappBillUrl(bill),'_blank','noopener,noreferrer');toast('PDF downloaded. Attach it to the WhatsApp message to share.');}catch(error){toast('Could not create the bill PDF. Try Print bill and choose Save as PDF.');}}
function openBillPreview(billId){const bill=store.bills.find(b=>b.id===billId);if(!bill)return;const lineRows=bill.lines?.length?bill.lines.map(line=>`<tr><td>${escapeHtml(line.productName)}</td><td>${line.quantity}</td><td>${money(line.unitPrice)}</td><td>${money(line.lineTotal)}</td></tr>`).join(''):`<tr><td>${bill.items} items</td><td>${bill.items}</td><td>—</td><td>${money(bill.total)}</td></tr>`;const payments=(bill.payments||[]).map(payment=>`<div class="invoice-payment"><span>${dateLabel(payment.date)} · ${escapeHtml(payment.method)}</span><strong>${money(payment.amount)}</strong></div>`).join('')||'<span class="muted-small">No payment recorded yet</span>';const due=dueAmount(bill),host=document.querySelector('#modal-content');host.innerHTML=`<div class="invoice-preview"><div class="invoice-brand"><img class="invoice-header-logo" src="bahipro-logo.jpeg" alt="BahiPro — Your Digital Munim"><div class="invoice-business"><span class="invoice-store-mark">${initials(store.profile.storeName)}</span><span><strong>${escapeHtml(store.profile.storeName)}</strong><small>${escapeHtml(store.profile.businessSector||'Retail')} · ${escapeHtml(store.profile.location)}</small></span></div><span class="invoice-title" id="modal-title">INVOICE</span></div><div class="invoice-meta"><div><span>Invoice number</span><strong>${escapeHtml(bill.id)}</strong></div><div><span>Date</span><strong>${dateLabel(bill.date)}</strong></div><div><span>Status</span><strong>${escapeHtml(bill.status)}</strong></div></div><div class="invoice-customer"><span>BILLED TO</span><strong>${escapeHtml(bill.customer)}</strong>${bill.customerCompanyName?`<small class="invoice-company">${escapeHtml(bill.customerCompanyName)}</small>`:''}<small>${escapeHtml(bill.phone||'')}</small></div><div class="table-wrap invoice-lines"><table><thead><tr><th>ITEM</th><th>QTY</th><th>PRICE</th><th>AMOUNT</th></tr></thead><tbody>${lineRows}</tbody></table></div><div class="invoice-totals"><div><span>Bill total</span><strong>${money(bill.total)}</strong></div><div><span>Paid</span><strong>${money(bill.paidAmount)}</strong></div><div class="invoice-balance"><span>Balance due</span><strong>${money(due)}</strong></div></div><div class="invoice-payment-history"><strong>Payment history</strong>${payments}</div><div class="invoice-due-footer ${due>0?'pending':''}"><span>${due>0?'AMOUNT PENDING':'PAYMENT COMPLETE'}</span><strong>${money(due)}</strong></div><p class="invoice-thanks">Thank you for shopping with us.</p><p class="invoice-powered">Generated with ${APP_NAME} · ${APP_TAGLINE}</p></div><div class="modal-actions invoice-actions"><a class="btn" href="${escapeHtml(whatsappBillUrl(bill))}" target="_blank" rel="noopener">WhatsApp message ↗</a><button type="button" class="btn" data-share-bill-pdf="${escapeHtml(bill.id)}">Share PDF on WhatsApp</button><button type="button" class="btn" data-print-bill>Print bill</button><button type="button" class="btn btn-primary" data-close>Done</button></div>`;document.querySelector('#modal-backdrop').hidden=false;document.querySelector('.modal-close').focus();}function openPaymentModal(id){const bill=store.bills.find(b=>b.id===id&&dueAmount(b)>0);if(!bill)return;const due=dueAmount(bill),host=document.querySelector('#modal-content');host.innerHTML=`<h2 id="modal-title">Add a payment</h2><p class="modal-intro">Record a full or partial payment for ${escapeHtml(bill.id)} from ${escapeHtml(bill.customer)}.</p><div class="payment-summary"><div><span>Bill total</span><strong>${money(bill.total)}</strong></div><div><span>Paid so far</span><strong>${money(bill.paidAmount)}</strong></div><div><span>Balance due</span><strong>${money(due)}</strong></div></div><form id="payment-form"><div class="form-field"><label for="payment-amount">Amount received (₹)</label><input class="field" id="payment-amount" type="number" min="0.01" max="${due.toFixed(2)}" step="0.01" value="${due.toFixed(2)}" required></div><div class="form-field"><label for="payment-method">Payment method received</label><select class="field" id="payment-method" required><option>UPI</option><option>Cash</option><option>Card</option><option>Bank transfer</option></select></div><p class="form-note">Enter less than the balance due to record a partial payment. You can add another payment later.</p><div class="modal-actions"><button type="button" class="btn" data-close>Cancel</button><button class="btn btn-primary" type="submit">Add payment</button></div></form>`;document.querySelector('#payment-form').addEventListener('submit',e=>{e.preventDefault();const amount=Number(document.querySelector('#payment-amount').value),currentDue=dueAmount(bill);if(!Number.isFinite(amount)||amount<=0||amount-currentDue>0.001){toast(`Enter an amount between ₹0.01 and ${money(currentDue)}.`);return;}const method=document.querySelector('#payment-method').value;bill.paidAmount=Math.min(Number(bill.total),Math.round((Number(bill.paidAmount||0)+amount)*100)/100);bill.payments.push({date:localISODate(),amount,method});bill.method=method;bill.status=dueAmount(bill)<=0.009?'Paid':'Pending';if(bill.status==='Paid')bill.paidAmount=Number(bill.total);const remaining=dueAmount(bill);saveStore();closeModal();renderPage();toast(remaining===0?`${bill.id} paid in full.`:`Payment added. ${money(remaining)} remains due.`);});document.querySelector('#modal-backdrop').hidden=false;document.querySelector('.modal-close').focus();}function openProfileModal(){const profile=store.profile;const host=document.querySelector('#modal-content');host.innerHTML=`<h2 id="modal-title">Your profile</h2><p class="modal-intro">Update your owner, business sector, and store details.</p><form id="profile-form"><div class="form-field"><label for="profile-name">Your name</label><input class="field" id="profile-name" required value="${escapeHtml(profile.name)}"></div><div class="form-field"><label for="profile-role">Role</label><input class="field" id="profile-role" value="${escapeHtml(profile.role)}"></div><div class="form-field"><label for="profile-sector">Business sector</label><input class="field" id="profile-sector" required value="${escapeHtml(profile.businessSector||'')}" placeholder="e.g. Grocery &amp; convenience retail"></div><div class="form-field"><label for="profile-store">Store name</label><input class="field" id="profile-store" required value="${escapeHtml(profile.storeName)}"></div><div class="form-field"><label for="profile-location">Store location</label><input class="field" id="profile-location" required value="${escapeHtml(profile.location)}"></div><div class="modal-actions"><button type="button" class="btn" data-close>Cancel</button><button class="btn btn-primary" type="submit">Save profile</button></div></form>`;document.querySelector('#profile-form').addEventListener('submit',e=>{e.preventDefault();store.profile={name:document.querySelector('#profile-name').value.trim(),role:document.querySelector('#profile-role').value.trim()||'Store owner',businessSector:document.querySelector('#profile-sector').value.trim(),storeName:document.querySelector('#profile-store').value.trim(),location:document.querySelector('#profile-location').value.trim()};saveStore();closeModal();syncProfile();renderPage();toast('Profile updated.');});document.querySelector('#modal-backdrop').hidden=false;document.querySelector('.modal-close').focus();}function syncProfile(){const profile=store.profile||seed.profile;document.querySelectorAll('[data-profile-name]').forEach(el=>el.textContent=profile.name);document.querySelectorAll('[data-profile-role]').forEach(el=>el.textContent=profile.role);document.querySelectorAll('[data-store-name]').forEach(el=>el.textContent=profile.storeName||'Set up your store');document.querySelectorAll('[data-store-location]').forEach(el=>el.textContent=profile.location||'Add store location');document.querySelectorAll('[data-profile-avatar]').forEach(el=>el.textContent=initials(profile.name));document.querySelectorAll('[data-store-avatar]').forEach(el=>el.textContent=initials(profile.storeName));}
function closeModal(){document.querySelector('#modal-backdrop').hidden=true;}

function exportCsv(kind){let filename,rows;if(kind==='bills'){filename='bahipro-bills.csv';rows=[['Invoice','Customer','Date','Items','Amount','Paid amount','Balance due','Status','Last payment method','Payment history'],...store.bills.map(b=>[b.id,b.customer,b.date,b.items,b.total,b.paidAmount,dueAmount(b),b.status,b.method,(b.payments||[]).map(p=>`${p.date}: ${p.amount} (${p.method})`).join(' | ')])];}else if(kind==='products'){filename='bahipro-inventory.csv';rows=[['Product ID','Product','Category','Selling price','Purchase rate','Rate source','Unit margin','Supplier','Last purchase date','Stock','Stock cost value','Reorder level','Status'],...store.products.map(p=>[p.id,p.name,p.category,p.price,p.purchaseRate,p.purchaseRateEstimated?'Estimated':'Recorded',p.price-p.purchaseRate,p.supplier||'',p.lastPurchaseDate||'',p.stock,p.stock*p.purchaseRate,p.reorder,p.stock<=p.reorder?'Restock':'In stock'])];}else if(kind==='purchases'){filename='bahipro-purchases.csv';rows=[['Purchase ID','Supplier invoice','Supplier','Date','Products','Units','Purchase total','Paid amount','Balance due','Status','Payment method'],...store.purchases.map(p=>[p.id,p.invoiceNumber||'',p.supplier,p.date,p.lines.map(line=>`${line.productName} × ${line.quantity} @ ${line.purchaseRate}`).join(' | '),p.items,p.total,p.paidAmount,purchaseDue(p),p.status,p.method])];}else{filename='bahipro-customers.csv';rows=[['Customer','Company','Phone','Email','Visits','Lifetime spend','Lifetime pending'],...store.customers.map(c=>[c.name,c.companyName||'',c.phone,c.email||'',c.visits,c.spent,customerPendingAmount(c)])];}const csv=rows.map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\r\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));link.download=filename;link.click();URL.revokeObjectURL(link.href);toast('Your CSV report is ready.');}function filterBills(){const query=document.querySelector('[data-table-search]')?.value.toLowerCase()||'',status=document.querySelector('#bill-filter')?.value||'all';const list=store.bills.filter(b=>(status==='all'||b.status===status)&&`${b.id} ${b.customer}`.toLowerCase().includes(query));document.querySelector('#bills-table').innerHTML=billRows(list,true);}
function filterProducts(){const query=document.querySelector('[data-table-search]')?.value.toLowerCase()||'',category=document.querySelector('#category-filter')?.value||'all';const list=store.products.filter(p=>(category==='all'||p.category===category)&&`${p.name} ${p.category} ${p.id} ${p.supplier||''}`.toLowerCase().includes(query));document.querySelector('#products-table').innerHTML=productRows(list);}
function filterCustomers(){const query=document.querySelector('[data-customer-search]')?.value.toLowerCase()||'';document.querySelector('#customer-grid').innerHTML=customerCards(store.customers.filter(c=>`${c.name} ${c.phone}`.toLowerCase().includes(query)));}
function updateNavBadge(){const count=store.bills.filter(b=>b.status==='Pending').length;document.querySelector('#pending-nav').textContent=count;}

