function buildBahiProSearchRecords(){
  return [
    ...store.bills.map(bill=>({page:'billing',query:bill.id,label:`${bill.id} · ${bill.customer}`,detail:`Bill · ${bill.status} · ${money(dueAmount(bill))} due`,text:`${bill.id} ${bill.customer} ${bill.customerCompanyName||''} ${bill.phone||''}`})),
    ...store.products.map(product=>({page:'inventory',query:product.name,label:product.name,detail:`Product · ${product.category} · ${product.stock} in stock`,text:`${product.name} ${product.category} ${product.id} ${product.supplier||''}`})),
    ...store.customers.map(customer=>({page:'customers',query:customer.name,label:customer.name,detail:`Customer · ${customer.companyName||customer.phone||'No company or phone'}`,text:`${customer.name} ${customer.companyName||''} ${customer.phone||''} ${customer.email||''}`})),
    ...store.purchases.map(purchase=>({page:'purchases',query:purchase.id,label:`${purchase.supplier} · ${purchase.id}`,detail:`Purchase · ${purchase.status} · ${money(purchaseDue(purchase))} due`,text:`${purchase.id} ${purchase.invoiceNumber||''} ${purchase.supplier}`}))
  ];
}

function renderGlobalSearchResults(value){
  const input=document.querySelector('#global-search'),panel=document.querySelector('#global-search-results');
  if(!input||!panel)return;
  const query=String(value||'').trim().toLowerCase();
  if(!query){panel.hidden=true;input.setAttribute('aria-expanded','false');panel.innerHTML='';return;}
  const matches=buildBahiProSearchRecords().filter(record=>record.text.toLowerCase().includes(query)).slice(0,10);
  panel.innerHTML=`<div class="search-results-heading">${matches.length?'Matching records':'Search'}</div>${matches.length?matches.map(record=>`<button type="button" class="search-result" role="option" data-global-page="${record.page}" data-global-query="${escapeHtml(record.query)}"><span><strong>${escapeHtml(record.label)}</strong><small>${escapeHtml(record.detail)}</small></span><em>${({billing:'BILL',inventory:'STOCK',customers:'CUSTOMER',purchases:'PURCHASE'})[record.page]}</em></button>`).join(''):`<div class="search-empty">No bills, customers, products, or purchases match “${escapeHtml(value)}”.</div>`}`;
  panel.hidden=false;input.setAttribute('aria-expanded','true');
}

function navigateToRecord(page,query){
  closeModal();
  setPage(page);
  const selector=({billing:'[data-table-search]',inventory:'[data-table-search]',customers:'[data-customer-search]',purchases:'[data-purchase-search]'})[page];
  const field=selector&&document.querySelector(selector);
  if(field){field.value=query;if(page==='billing')filterBills();if(page==='inventory')filterProducts();if(page==='customers')filterCustomers();if(page==='purchases')filterPurchases();}
  const search=document.querySelector('#global-search');if(search)search.value='';
  renderGlobalSearchResults('');
}

function getBahiProNotifications(){
  const lowStock=store.products.filter(product=>Number(product.stock)<=Number(product.reorder)).map(product=>({kind:'stock',symbol:'!',page:'inventory',query:product.name,title:`${product.name} needs restocking`,detail:`${product.stock} in stock · reorder at ${product.reorder}`}));
  const unpaidBills=store.bills.filter(bill=>dueAmount(bill)>0).map(bill=>({kind:'pending',symbol:'₹',page:'billing',query:bill.id,title:`${bill.id} · ${bill.customer}`,detail:`${money(dueAmount(bill))} payment pending`}));
  const unpaidPurchases=store.purchases.filter(purchase=>purchaseDue(purchase)>0).map(purchase=>({kind:'pending',symbol:'₹',page:'purchases',query:purchase.id,title:`${purchase.supplier} · ${purchase.id}`,detail:`${money(purchaseDue(purchase))} supplier payment due`}));
  return [...lowStock,...unpaidBills,...unpaidPurchases];
}

function updateNavBadge(){
  const count=store.bills.filter(bill=>dueAmount(bill)>0).length;
  const nav=document.querySelector('#pending-nav');if(nav)nav.textContent=count;
  const alerts=getBahiProNotifications(),badge=document.querySelector('#notification-badge'),button=document.querySelector('[data-open-notifications]');
  if(badge){badge.textContent=alerts.length>99?'99+':String(alerts.length);badge.hidden=alerts.length===0;}
  if(button){button.setAttribute('aria-label',alerts.length?`Notifications, ${alerts.length} alerts`:'Notifications, no new alerts');button.title=alerts.length?`${alerts.length} store alerts`:'No store alerts';}
}

function openBahiProNotifications(){
  const alerts=getBahiProNotifications(),host=document.querySelector('#modal-content');
  host.innerHTML=`<h2 id="modal-title">Notifications</h2><p class="modal-intro">Stock reminders, unpaid customer bills, and supplier balances from this workspace.</p>${alerts.length?`<div class="notification-list">${alerts.slice(0,20).map(alert=>`<button type="button" class="notification-item ${alert.kind}" data-notification-page="${alert.page}" data-notification-query="${escapeHtml(alert.query)}"><span class="notification-symbol">${alert.symbol}</span><span><strong>${escapeHtml(alert.title)}</strong><small>${escapeHtml(alert.detail)}</small></span></button>`).join('')}</div>${alerts.length>20?`<p class="form-note">Showing 20 of ${alerts.length} alerts. Open the related section to review the full list.</p>`:''}`:'<div class="search-empty">You’re all caught up. No low-stock items or unpaid balances need attention.</div>'}`;
  document.querySelector('#modal-backdrop').hidden=false;document.querySelector('.modal-close').focus();
}

function openBahiProHelp(){
  const host=document.querySelector('#modal-content');
  host.innerHTML=`<h2 id="modal-title">BahiPro help</h2><p class="modal-intro">Quick ways to get around your billing and store workspace.</p><div class="help-grid"><article class="help-card"><strong>Create a bill</strong><p>Add a customer and multiple products, record full or partial payment, then preview or share the invoice.</p><button type="button" data-action="new-bill">Create a bill →</button></article><article class="help-card"><strong>Manage products and stock</strong><p>Update selling and purchase rates, supplier details, stock counts, and reorder levels.</p><button type="button" data-help-page="inventory">Open inventory →</button></article><article class="help-card"><strong>Customers and pending balances</strong><p>Review customer history, lifetime spend, and the balance still due.</p><button type="button" data-help-page="customers">Open customers →</button></article><article class="help-card"><strong>Reports and exports</strong><p>Download CSV or analytics data, or configure automatic Google Sheets updates.</p><button type="button" data-help-page="reports">Open reports →</button></article></div><p class="form-note">Each browser profile gets its own workspace. Another device starts separately; use the analysis export and import to move or back up data. Anyone using this same browser profile can open its workspace.</p><div class="modal-actions"><button type="button" class="btn btn-primary" data-start-tour>Take the guided tour</button></div>`;
  document.querySelector('#modal-backdrop').hidden=false;document.querySelector('.modal-close').focus();
}

document.addEventListener('input',event=>{if(event.target.id==='global-search')renderGlobalSearchResults(event.target.value);});
document.addEventListener('focusin',event=>{if(event.target.id==='global-search'&&event.target.value)renderGlobalSearchResults(event.target.value);});
document.addEventListener('click',event=>{
  if(event.target.closest('[data-open-help]'))openBahiProHelp();
  if(event.target.closest('[data-open-notifications]'))openBahiProNotifications();
  const result=event.target.closest('[data-global-page]');
  if(result){navigateToRecord(result.dataset.globalPage,result.dataset.globalQuery);return;}
  const notification=event.target.closest('[data-notification-page]');
  if(notification){navigateToRecord(notification.dataset.notificationPage,notification.dataset.notificationQuery);return;}
  const helpPage=event.target.closest('[data-help-page]');
  if(helpPage){navigateToRecord(helpPage.dataset.helpPage,'');return;}
  if(!event.target.closest('.global-search-wrap'))renderGlobalSearchResults('');
});
document.addEventListener('keydown',event=>{
  if(event.target.id==='global-search'&&event.key==='Enter'){
    const first=document.querySelector('#global-search-results [data-global-page]');
    if(first){event.preventDefault();navigateToRecord(first.dataset.globalPage,first.dataset.globalQuery);}
  }
  if(event.key==='Escape')renderGlobalSearchResults('');
});

function bahiProRestockPlan(product){
  const cutoff=new Date();cutoff.setDate(cutoff.getDate()-30);const cutoffDate=localISODate(cutoff);
  const soldRecently=store.bills.filter(bill=>String(bill.date||'')>=cutoffDate).reduce((sum,bill)=>sum+(bill.lines||[]).filter(line=>line.productId===product.id||line.productName===product.name).reduce((lineSum,line)=>lineSum+Number(line.quantity||0),0),0);
  const reorder=Number(product.reorder||0),target=Math.max(reorder*2,Math.ceil(soldRecently*1.5),reorder+1);
  return{target,quantity:Math.max(0,target-Number(product.stock||0)),soldRecently};
}

function buildBahiProAISuggestions(){
  const suggestions=[],low=lowStock(),pendingBills=store.bills.filter(bill=>dueAmount(bill)>0),pendingTotal=pendingBills.reduce((sum,bill)=>sum+dueAmount(bill),0);
  if(low.length){
    const plans=low.slice(0,3).map(product=>`${product.name}: add about ${bahiProRestockPlan(product).quantity}`).join('; '),extra=low.length>3?`; ${low.length-3} more need review`:'';
    suggestions.push({icon:'▦',title:`Restock ${low.length} low-stock ${low.length===1?'item':'items'}`,body:`Suggested top-ups: ${plans}${extra}. Quantities aim for roughly twice the reorder point, adjusted for recent sales.`,page:'inventory',action:'Review inventory'});
  }
  if(pendingTotal){
    const oldest=pendingBills.slice().sort((a,b)=>String(a.date||'').localeCompare(String(b.date||'')))[0];
    suggestions.push({icon:'₹',title:`Follow up on ${money(pendingTotal)} due`,body:`${pendingBills.length} bill${pendingBills.length===1?'':'s'} still have a balance. ${oldest?`${oldest.id} is the oldest open bill.`:''}`,page:'billing',action:'Review pending bills'});
  }
  const now=new Date(),thisMonth=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0'),previousDate=new Date(now.getFullYear(),now.getMonth()-1,1),previousMonth=previousDate.getFullYear()+'-'+String(previousDate.getMonth()+1).padStart(2,'0'),currentSales=sumBills(store.bills.filter(bill=>String(bill.date||'').startsWith(thisMonth))),previousSales=sumBills(store.bills.filter(bill=>String(bill.date||'').startsWith(previousMonth)));
  if(currentSales||previousSales){
    const body=previousSales?`Recorded sales are ${currentSales>=previousSales?'up':'down'} ${Math.abs(Math.round((currentSales-previousSales)/previousSales*100))}% versus last month (${money(currentSales)} vs ${money(previousSales)}).`:`${money(currentSales)} in sales recorded so far this month. There were no sales recorded last month for comparison.`;
    suggestions.push({icon:'↗',title:'Monthly sales pulse',body,page:'reports',action:'Open reports'});
  }
  const best=topSellingProducts()[0];
  if(best)suggestions.push({icon:'★',title:`${best.name} leads recorded sales`,body:`${best.quantity} units sold in saved bills. Check its current stock before your next order.`,page:'inventory',action:'Check product stock'});
  if(!suggestions.length)suggestions.push({icon:'✦',title:'Start with your first bill',body:'Once you record sales, BahiPro can highlight top products, monthly sales movement, and customer balances.',page:'billing',action:'Create a bill'});
  return suggestions.slice(0,4);
}

function bahiProAIAnswer(question){
  const query=String(question||'').trim().toLowerCase(),now=new Date(),month=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0'),monthBills=store.bills.filter(bill=>String(bill.date||'').startsWith(month)),monthSales=sumBills(monthBills),monthCollected=sumCollected(monthBills),openBills=store.bills.filter(bill=>dueAmount(bill)>0),dueTotal=openBills.reduce((sum,bill)=>sum+dueAmount(bill),0),low=lowStock();
  if(/pending|due|owe|unpaid|collect|balance/.test(query)){
    if(!dueTotal)return 'There are no customer bill balances pending in this workspace.';
    const examples=openBills.slice().sort((a,b)=>dueAmount(b)-dueAmount(a)).slice(0,3).map(bill=>`${bill.id} (${bill.customer}: ${money(dueAmount(bill))})`).join(', ');
    return `${money(dueTotal)} is pending across ${openBills.length} bill${openBills.length===1?'':'s'}. Largest balances: ${examples}. Open Billing to record a payment or follow up.`;
  }
  if(/stock|inventory|restock|reorder/.test(query)){
    if(!low.length)return 'All products are currently above their reorder levels.';
    const list=low.slice(0,5).map(product=>`${product.name}: ${product.stock} left; consider adding about ${bahiProRestockPlan(product).quantity}`).join('; ');
    return `${low.length} product${low.length===1?'':'s'} need attention: ${list}. Suggested quantities aim for roughly twice each reorder point and account for recent 30-day sales. Review Inventory before ordering.`;
  }
  if(/sales|revenue|month|today|collection/.test(query)){
    const today=localISODate(),todaySales=sumBills(store.bills.filter(bill=>bill.date===today));
    return `This month: ${money(monthSales)} recorded across ${monthBills.length} bill${monthBills.length===1?'':'s'}, with ${money(monthCollected)} collected and ${money(Math.max(0,monthSales-monthCollected))} still due. Today's sales are ${money(todaySales)}.`;
  }
  if(/top|best|popular|selling|product|sold/.test(query)){
    const best=topSellingProducts();
    return best.length?`Top products by units in saved bills: ${best.slice(0,3).map((product,index)=>`${index+1}. ${product.name} (${product.quantity} sold)`).join('; ')}.`:'No bill line items are recorded yet. Save bills with products to see top sellers.';
  }
  if(/customer|client|buyer/.test(query)){
    const biggest=store.customers.slice().sort((a,b)=>Number(b.spent||0)-Number(a.spent||0))[0];
    return `${store.customers.length} customer${store.customers.length===1?'':'s'} saved. ${biggest?`${biggest.name} has the highest recorded lifetime spend at ${money(biggest.spent)}.`:'Add customers while billing to build customer history.'}`;
  }
  if(/purchase|supplier|payable/.test(query)){
    const open=store.purchases.filter(purchase=>purchaseDue(purchase)>0),due=open.reduce((sum,purchase)=>sum+purchaseDue(purchase),0),total=sumBills(store.purchases);
    return `${store.purchases.length} purchase${store.purchases.length===1?'':'s'} recorded for ${money(total)} total. ${money(due)} remains payable across ${open.length} purchase${open.length===1?'':'s'}.`;
  }
  if(/profit|margin|cost/.test(query)){
    let estimate=0,estimatedRates=false;
    store.bills.forEach(bill=>(bill.lines||[]).forEach(line=>{const product=store.products.find(item=>item.id===line.productId||item.name===line.productName);if(product){estimate+=(Number(line.unitPrice||0)-Number(product.purchaseRate||0))*Number(line.quantity||0);if(product.purchaseRateEstimated)estimatedRates=true;}}));
    return `Estimated gross margin on saved bill items is ${money(estimate)}, using each product's current purchase rate. ${estimatedRates?'Some purchase rates are estimates, so treat this as a rough guide.':'This is a guide, not an accounting profit figure.'}`;
  }
  return 'I can help with sales, pending payments, stock and reorder items, top products, customers, purchases, and estimated margins. Try one of the example questions below.';
}

function bahiProAIPanel(){
  const suggestions=buildBahiProAISuggestions();
  return `<section class="panel ai-assistant-panel"><div class="ai-panel-heading"><span class="ai-spark">✦</span><div><p class="eyebrow">YOUR LOCAL SMART ASSISTANT</p><h2>AI suggestions</h2><p>Ideas based on the bills, stock, and customers saved in this browser.</p></div><span class="ai-local-tag">Local analysis</span></div><div class="ai-suggestions" id="ai-suggestions">${suggestions.map(item=>`<article class="ai-suggestion"><span class="ai-suggestion-icon">${item.icon}</span><div><strong>${escapeHtml(item.title)}</strong><p>${escapeHtml(item.body)}</p><button type="button" data-ai-page="${item.page}">${escapeHtml(item.action)} →</button></div></article>`).join('')}</div><div class="ai-assistant"><div class="ai-assistant-title"><strong>Ask BahiPro</strong><small>Local data only · Python backend optional</small></div><form id="ai-question-form" class="ai-question-form"><input class="field" id="ai-question" type="search" placeholder="Try: What payments are pending?" aria-label="Ask BahiPro about your store"><button class="btn btn-primary" type="submit">Ask</button></form><div class="ai-prompts"><button type="button" data-ai-prompt="What should I restock?">What should I restock?</button><button type="button" data-ai-prompt="How much is pending?">How much is pending?</button><button type="button" data-ai-prompt="What sold the most?">What sold the most?</button><button type="button" data-ai-prompt="How are sales this month?">Sales this month</button></div><p class="ai-answer" id="ai-answer" aria-live="polite">Ask about sales, payments, stock, products, customers, purchases, or margins.</p></div><p class="ai-disclosure">BahiPro uses local Python and SQL rules when the server is running, with a browser fallback. These are decision aids, not forecasts.</p></section>`;
}

