function fieldValue(selector){return document.querySelector(selector)?.value||'';}

function getPythonWorkspaceId(){
  let id=localStorage.getItem(WORKSPACE_ID_KEY)||'';
  if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id)){
    if(window.crypto?.randomUUID)id=window.crypto.randomUUID();
    else{
      const bytes=new Uint8Array(16);
      window.crypto.getRandomValues(bytes);
      bytes[6]=(bytes[6]&0x0f)|0x40;
      bytes[8]=(bytes[8]&0x3f)|0x80;
      const hex=Array.from(bytes,value=>value.toString(16).padStart(2,'0')).join('');
      id=`${hex.slice(0,8)}-${hex.slice(8,12)}-${hex.slice(12,16)}-${hex.slice(16,20)}-${hex.slice(20)}`;
    }
    localStorage.setItem(WORKSPACE_ID_KEY,id);
  }
  return id;
}

function workspaceRequestHeaders(headers={}){
  return {...headers,'X-BahiPro-Workspace':getPythonWorkspaceId()};
}

async function askBahiPro(question){
  const answerPanel=document.querySelector('#ai-answer');
  if(!answerPanel)return;
  answerPanel.textContent='Checking your saved store data…';
  try{
    const response=await fetch('/api/assistant',{method:'POST',headers:workspaceRequestHeaders({'Content-Type':'application/json'}),body:JSON.stringify({question})});
    const result=await response.json();
    if(!response.ok)throw new Error(result.error||'Python assistant is unavailable.');
    answerPanel.textContent=result.answer;
  }catch(error){answerPanel.textContent=bahiProAIAnswer(question);}
}

function normalizePythonWorkspace(workspace){
  const loaded=structuredClone(workspace||seed);
  loaded.profile={...seed.profile,...(loaded.profile||{})};
  loaded.products=Array.isArray(loaded.products)?loaded.products:[];
  loaded.customers=Array.isArray(loaded.customers)?loaded.customers:[];
  loaded.bills=Array.isArray(loaded.bills)?loaded.bills:[];
  loaded.purchases=Array.isArray(loaded.purchases)?loaded.purchases:[];
  loaded.products.forEach(product=>{if(!Number.isFinite(Number(product.purchaseRate))){product.purchaseRate=Math.round(Number(product.price||0)*0.8*100)/100;product.purchaseRateEstimated=true;}if(!product.supplier)product.supplier='Opening stock';if(!product.lastPurchaseDate)product.lastPurchaseDate='';});
  loaded.bills.forEach(normalizeBill);
  return loaded;
}

function saveWorkspaceToPython(snapshot){
  const serialized=JSON.stringify(snapshot);
  pythonSaveQueue=pythonSaveQueue.catch(()=>{}).then(async()=>{
    const response=await fetch('/api/workspace',{method:'PUT',headers:workspaceRequestHeaders({'Content-Type':'application/json'}),body:JSON.stringify({workspace:snapshot})});
    const result=await response.json();
    if(!response.ok)throw new Error(result.error||'Python could not save the workspace.');
    if(localStorage.getItem(STORAGE_KEY)===serialized){
      const stamp=Date.parse(result.updatedAt||'');
      if(stamp)localStorage.setItem(LOCAL_UPDATED_KEY,String(stamp));
    }
    return result;
  });
  return pythonSaveQueue;
}

async function loadPythonSuggestions(){
  try{
    const response=await fetch('/api/analytics/suggestions',{headers:workspaceRequestHeaders()});
    if(!response.ok)return;
    const result=await response.json(),host=document.querySelector('#ai-suggestions');
    if(host&&Array.isArray(result.suggestions))host.innerHTML=result.suggestions.map(item=>`<article class="ai-suggestion"><span class="ai-suggestion-icon">${escapeHtml(item.icon||'✦')}</span><div><strong>${escapeHtml(item.title)}</strong><p>${escapeHtml(item.body)}</p><button type="button" data-ai-page="${escapeHtml(item.page)}">${escapeHtml(item.action)} →</button></div></article>`).join('');
  }catch(error){}
}

async function connectPythonBackend(){
  if(pythonBackendConnected||pythonBackendConnecting)return;
  pythonBackendConnecting=true;
  try{
    const response=await fetch('/api/workspace',{headers:workspaceRequestHeaders()});
    if(!response.ok)throw new Error('Python API is unavailable.');
    const remote=await response.json();
    let cached=null;
    try{cached=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');}catch(error){}
    const localStamp=Number(localStorage.getItem(LOCAL_UPDATED_KEY)||0),serverStamp=Date.parse(remote.updatedAt||'')||0;
    if(remote.workspace&&cached&&localStamp>serverStamp){
      store=normalizePythonWorkspace(cached);
      localStorage.setItem(STORAGE_KEY,JSON.stringify(store));
      await saveWorkspaceToPython(store);
    }else if(remote.workspace){
      store=normalizePythonWorkspace(remote.workspace);
      localStorage.setItem(STORAGE_KEY,JSON.stringify(store));
      localStorage.setItem(LOCAL_UPDATED_KEY,String(serverStamp||Date.now()));
    }else{
      store=normalizePythonWorkspace(store);
      localStorage.setItem(STORAGE_KEY,JSON.stringify(store));
      await saveWorkspaceToPython(store);
    }
    pythonBackendConnected=true;
    const status=document.querySelector('#save-status');if(status){status.textContent='✓ Workspace saved to Python + SQLite';status.classList.remove('save-error');}
    const storageMode=document.querySelector('[data-storage-mode]');if(storageMode)storageMode.textContent='Python + SQLite server · this browser workspace';
    const source=document.querySelector('.ai-assistant-title small');if(source)source.textContent='Python + SQLite · this browser workspace';
    const badge=document.querySelector('.ai-local-tag');if(badge)badge.textContent='Python + SQLite';
    updateNavBadge();renderPage();maybeStartGuidedTour();
  }catch(error){
    pythonBackendConnected=false;
    const status=document.querySelector('#save-status');if(status)status.textContent='✓ Saved in this browser · Python offline';
    const storageMode=document.querySelector('[data-storage-mode]');if(storageMode)storageMode.textContent='Browser storage · Python not connected';
    maybeStartGuidedTour();
  }finally{
    pythonBackendConnecting=false;
  }
}

window.addEventListener('online',()=>{if(!pythonBackendConnected)connectPythonBackend();});
setInterval(()=>{if(!pythonBackendConnected)connectPythonBackend();},10000);
document.addEventListener('click',event=>{
  if(event.target.closest('[data-action="import-workspace"]'))document.querySelector('#workspace-import-file')?.click();
});
document.addEventListener('change',async event=>{
  if(event.target.id!=='workspace-import-file'||!event.target.files?.[0])return;
  try{
    const input=event.target,source=JSON.parse(await input.files[0].text()),workspace=source.workspace||source;
    if(!workspace||!workspace.profile||!Array.isArray(workspace.products)||!Array.isArray(workspace.bills)||!Array.isArray(workspace.customers)||!Array.isArray(workspace.purchases))throw new Error('Choose a BahiPro analysis JSON export.');
    store=normalizePythonWorkspace(workspace);saveStore();updateNavBadge();renderPage();toast('Previous BahiPro workspace imported.');
  }catch(error){toast(error.message||'Could not import that file.');}
  event.target.value='';
});

function workspaceIsEmpty(){
  return !String(store.profile?.name||'').trim()&&!String(store.profile?.storeName||'').trim()&&store.products.length===0&&store.bills.length===0&&store.customers.length===0&&store.purchases.length===0;
}

function maybeStartGuidedTour(){
  if(guidedTourActive||guidedTourScheduled)return;
  try{if(localStorage.getItem(TOUR_SEEN_KEY)==='1')return;}catch(error){}
  if(!workspaceIsEmpty()){
    try{localStorage.setItem(TOUR_SEEN_KEY,'1');}catch(error){}
    return;
  }
  guidedTourScheduled=true;
  setTimeout(()=>{
    guidedTourScheduled=false;
    if(!guidedTourActive&&workspaceIsEmpty())startGuidedTour();
  },500);
}

function startGuidedTour(){
  if(guidedTourActive)return;
  guidedTourActive=true;guidedTourStep=0;closeModal();
  const overlay=document.querySelector('#guided-tour');
  if(!overlay)return;
  overlay.hidden=false;overlay.setAttribute('aria-hidden','false');
  window.addEventListener('resize',positionGuidedTour);
  showGuidedTourStep(0);
}

function setTourShade(id,left,top,width,height){
  const shade=document.querySelector(id);
  if(!shade)return;
  if(width<=0||height<=0){shade.style.display='none';return;}
  shade.style.display='block';shade.style.left=`${left}px`;shade.style.top=`${top}px`;shade.style.width=`${width}px`;shade.style.height=`${height}px`;
}

function positionGuidedTour(){
  if(!guidedTourActive)return;
  const step=guidedTourSteps[guidedTourStep],target=step.target?document.querySelector(step.target):null,outline=document.querySelector('#tour-outline'),width=window.innerWidth,height=window.innerHeight;
  if(!target){setTourShade('#tour-shade-top',0,0,width,height);setTourShade('#tour-shade-left',0,0,0,0);setTourShade('#tour-shade-right',0,0,0,0);setTourShade('#tour-shade-bottom',0,0,0,0);outline.style.display='none';return;}
  const rect=target.getBoundingClientRect(),pad=8,left=Math.max(0,rect.left-pad),top=Math.max(0,rect.top-pad),right=Math.min(width,rect.right+pad),bottom=Math.min(height,rect.bottom+pad);
  outline.style.display='block';outline.style.left=`${left}px`;outline.style.top=`${top}px`;outline.style.width=`${Math.max(0,right-left)}px`;outline.style.height=`${Math.max(0,bottom-top)}px`;
  setTourShade('#tour-shade-top',0,0,width,top);
  setTourShade('#tour-shade-left',0,top,left,Math.max(0,bottom-top));
  setTourShade('#tour-shade-right',right,top,Math.max(0,width-right),Math.max(0,bottom-top));
  setTourShade('#tour-shade-bottom',0,bottom,width,Math.max(0,height-bottom));
}

function showGuidedTourStep(index){
  guidedTourStep=Math.max(0,Math.min(index,guidedTourSteps.length-1));
  const step=guidedTourSteps[guidedTourStep],card=document.querySelector('#tour-card');
  if(step.page&&currentPage!==step.page)setPage(step.page);
  document.querySelector('#tour-title').textContent=step.title;
  document.querySelector('#tour-description').textContent=step.description;
  document.querySelector('#tour-progress').textContent=`Step ${guidedTourStep+1} of ${guidedTourSteps.length}`;
  document.querySelector('[data-tour-back]').hidden=guidedTourStep===0;
  document.querySelector('[data-tour-next]').textContent=guidedTourStep===guidedTourSteps.length-1?'Finish':guidedTourStep===0?'Start tour':'Next';
  card.classList.toggle('centered',!step.target);
  requestAnimationFrame(positionGuidedTour);
  document.querySelector('[data-tour-next]').focus();
}

function finishGuidedTour(){
  if(!guidedTourActive)return;
  guidedTourActive=false;window.removeEventListener('resize',positionGuidedTour);
  const overlay=document.querySelector('#guided-tour');overlay.hidden=true;overlay.setAttribute('aria-hidden','true');
  try{localStorage.setItem(TOUR_SEEN_KEY,'1');}catch(error){}
  if(currentPage!=='overview')setPage('overview');
  document.querySelector('.nav-item[data-page="overview"]')?.focus();
}

document.addEventListener('click',event=>{
  if(event.target.closest('[data-start-tour]')){closeModal();startGuidedTour();return;}
  if(event.target.closest('[data-tour-skip]')){finishGuidedTour();return;}
  if(event.target.closest('[data-tour-back]')){showGuidedTourStep(guidedTourStep-1);return;}
  if(event.target.closest('[data-tour-next]')){if(guidedTourStep===guidedTourSteps.length-1)finishGuidedTour();else showGuidedTourStep(guidedTourStep+1);}
});

document.addEventListener('keydown',event=>{
  if(!guidedTourActive)return;
  if(event.key==='Tab'){
    const focusable=[...document.querySelectorAll('#tour-card button:not([hidden])')],first=focusable[0],last=focusable[focusable.length-1];
    if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}
    else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}
  }
  else if(event.key==='Escape'){event.preventDefault();finishGuidedTour();}
  else if(event.key==='ArrowRight'){event.preventDefault();if(guidedTourStep===guidedTourSteps.length-1)finishGuidedTour();else showGuidedTourStep(guidedTourStep+1);}
  else if(event.key==='ArrowLeft'&&guidedTourStep>0){event.preventDefault();showGuidedTourStep(guidedTourStep-1);}
});























